insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('c3000000-0000-0000-0000-000000000001', 'ukmla', '35e4a39f-c62a-4bdd-9513-716ddcb6b506',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('c3000000-0000-0000-0000-000000000001', 'A', 'Pemphigus vulgaris', false, $x$Ruled out because pemphigus vulgaris causes flaccid blisters with a positive Nikolsky's sign and prominent mucosal involvement, which are absent here.$x$, 1),
('c3000000-0000-0000-0000-000000000001', 'B', 'Dermatitis herpetiformis', false, 'Ruled out because dermatitis herpetiformis causes small, intensely itchy grouped vesicles on extensor surfaces associated with coeliac disease, typically in younger patients, not large tense bullae in an elderly woman.', 2),
('c3000000-0000-0000-0000-000000000001', 'C', 'Bullous pemphigoid', true, $x$Correct. The patient's age, pruritus preceding tense bullae on an erythematous base, negative Nikolsky's sign, and absence of mucosal involvement are all classic for bullous pemphigoid, a subepidermal blistering disorder.$x$, 3),
('c3000000-0000-0000-0000-000000000001', 'D', 'Bullous impetigo', false, 'Ruled out because bullous impetigo is a superficial staphylococcal infection more common in children, causing flaccid blisters that rupture into honey-coloured crusts, not tense bullae in an elderly patient.', 4),
('c3000000-0000-0000-0000-000000000001', 'E', 'Erythema multiforme', false, 'Ruled out because erythema multiforme typically presents with target lesions, often following herpes simplex infection, rather than this pattern of tense bullae.', 5),
('c3000000-0000-0000-0000-000000000002', 'A', 'Bullous pemphigoid', false, $x$Ruled out because bullous pemphigoid causes tense bullae with a negative Nikolsky's sign, and oral involvement is rare.$x$, 1),
('c3000000-0000-0000-0000-000000000002', 'B', 'Stevens-Johnson syndrome', false, 'Ruled out because SJS is typically drug-triggered with an acute onset, widespread mucocutaneous target lesions and systemic upset, which do not fit this chronic 6-week course with no drug history.', 2),
('c3000000-0000-0000-0000-000000000002', 'C', 'Dermatitis herpetiformis', false, $x$Ruled out because dermatitis herpetiformis causes grouped pruritic vesicles on extensor surfaces, not oral erosions with a positive Nikolsky's sign.$x$, 3),
('c3000000-0000-0000-0000-000000000002', 'D', 'Pemphigus vulgaris', true, $x$Correct. Painful oral erosions as an early feature, flaccid bullae, and a positive Nikolsky's sign (epidermal shearing under lateral pressure) reflect an intraepidermal, acantholytic blistering process typical of pemphigus vulgaris.$x$, 4),
('c3000000-0000-0000-0000-000000000002', 'E', 'Aphthous stomatitis', false, $x$Ruled out because aphthous stomatitis causes recurrent painful oral ulcers without skin blistering or a positive Nikolsky's sign.$x$, 5),
('c3000000-0000-0000-0000-000000000003', 'A', $x$Crohn's disease$x$, false, $x$Ruled out because Crohn's disease can cause cutaneous manifestations such as pyoderma gangrenosum or erythema nodosum, not this vesicular extensor eruption with granular IgA on biopsy.$x$, 1),
('c3000000-0000-0000-0000-000000000003', 'B', 'Chronic hepatitis C infection', false, 'Ruled out because hepatitis C is associated with porphyria cutanea tarda and lichen planus, not dermatitis herpetiformis.', 2),
('c3000000-0000-0000-0000-000000000003', 'C', 'Type 1 diabetes mellitus', false, 'Ruled out because type 1 diabetes is not classically linked to dermatitis herpetiformis; necrobiosis lipoidica is the skin condition linked to diabetes, with a different presentation.', 3),
('c3000000-0000-0000-0000-000000000003', 'D', 'Systemic lupus erythematosus', false, 'Ruled out because SLE causes a variety of skin rashes but not this grouped vesicular extensor eruption with granular IgA deposition.', 4),
('c3000000-0000-0000-0000-000000000003', 'E', 'Coeliac disease', true, 'Correct. Dermatitis herpetiformis is a cutaneous manifestation of gluten sensitivity, with granular IgA deposits in the dermal papillae and associated gastrointestinal symptoms and iron-deficiency anaemia from malabsorption, as seen here.', 5),
('c3000000-0000-0000-0000-000000000004', 'A', 'Polymorphic eruption of pregnancy', false, 'Ruled out because PEP typically arises within striae in the third trimester as non-blistering papules/plaques, with a negative direct immunofluorescence, unlike this case.', 1),
('c3000000-0000-0000-0000-000000000004', 'B', 'Pemphigoid gestationis', true, 'Correct. This rare autoimmune blistering disorder of pregnancy classically begins periumbilically with linear C3 (with or without IgG) at the basement membrane zone, and is associated with a small increase in risk of prematurity and low birth weight.', 2),
('c3000000-0000-0000-0000-000000000004', 'C', 'Impetigo herpetiformis', false, 'Ruled out because impetigo herpetiformis describes generalised pustular psoriasis of pregnancy with pustules, not tense blisters, and no linear C3 at the basement membrane zone.', 3),
('c3000000-0000-0000-0000-000000000004', 'D', 'Atopic eruption of pregnancy', false, 'Ruled out because this, the most common pregnancy dermatosis, presents as eczematous or papular lesions without blistering, with a negative direct immunofluorescence.', 4),
('c3000000-0000-0000-0000-000000000004', 'E', 'Bullous impetigo', false, 'Ruled out because bullous impetigo is a superficial bacterial infection causing flaccid blisters with honey-coloured crust, unrelated to pregnancy and not associated with linear C3 at the basement membrane zone.', 5),
('c3000000-0000-0000-0000-000000000005', 'A', 'Patient A: bullous pemphigoid; Patient B: pemphigus vulgaris', true, $x$Correct. Linear BMZ IgG/C3 with a negative Nikolsky's sign is characteristic of bullous pemphigoid (subepidermal split), whereas intercellular chicken-wire IgG with a positive Nikolsky's sign is characteristic of pemphigus vulgaris (intraepidermal, acantholytic split).$x$, 1),
('c3000000-0000-0000-0000-000000000005', 'B', 'Patient A: pemphigus vulgaris; Patient B: bullous pemphigoid', false, 'Ruled out because this reverses the assignment; the immunofluorescence and clinical patterns described do not match this combination.', 2),
('c3000000-0000-0000-0000-000000000005', 'C', 'Patient A: dermatitis herpetiformis; Patient B: bullous pemphigoid', false, 'Ruled out because dermatitis herpetiformis shows granular IgA in the dermal papillae, not linear IgG/C3, and does not typically present with large tense bullae in the elderly.', 3),
('c3000000-0000-0000-0000-000000000005', 'D', 'Patient A: bullous pemphigoid; Patient B: dermatitis herpetiformis', false, $x$Ruled out because patient B's findings (intercellular IgG, positive Nikolsky's sign, oral erosions) are typical of pemphigus vulgaris, not dermatitis herpetiformis.$x$, 4),
('c3000000-0000-0000-0000-000000000005', 'E', 'Both patients have pemphigus vulgaris with differing biopsy sites', false, 'Ruled out because the differing immunofluorescence patterns and clinical signs represent two distinct diagnoses, not variable biopsy sites of the same disease.', 5),
('c3000000-0000-0000-0000-000000000006', 'A', 'Stop the DPP-4 inhibitor and refer to dermatology for treatment of bullous pemphigoid', true, 'Correct. Gliptins are a recognised cause of drug-induced bullous pemphigoid; the causative drug should be withdrawn (in discussion with the prescriber) alongside standard dermatological treatment such as potent topical or systemic corticosteroids.', 1),
('c3000000-0000-0000-0000-000000000006', 'B', 'Continue the DPP-4 inhibitor and start oral prednisolone only', false, 'Ruled out because continuing a likely causative drug will hinder resolution and delay improvement; the drug should be reviewed and stopped where possible.', 2),
('c3000000-0000-0000-0000-000000000006', 'C', 'Switch to a different DPP-4 inhibitor in the same class', false, 'Ruled out because a class effect exists across gliptins, so switching to another agent in the same class risks recurrence.', 3),
('c3000000-0000-0000-0000-000000000006', 'D', 'Reassure the patient this is unrelated to medication and manage with emollients alone', false, 'Ruled out because emollients alone are inadequate for active bullous pemphigoid, and a genuine drug association should not be dismissed.', 4),
('c3000000-0000-0000-0000-000000000006', 'E', 'Arrange skin swabs for bacterial culture and start empirical flucloxacillin', false, 'Ruled out because there is no evidence of bacterial superinfection here; the priority is addressing the autoimmune blistering process and its likely drug trigger.', 5),
('c3000000-0000-0000-0000-000000000007', 'A', 'Continue carbamazepine and add an antihistamine for symptomatic relief', false, 'Ruled out because continuing the causative drug will worsen SJS/TEN progression; this is a dermatological emergency requiring drug withdrawal.', 1),
('c3000000-0000-0000-0000-000000000007', 'B', 'Switch to an alternative anticonvulsant from the same aromatic class (e.g. phenytoin)', false, 'Ruled out because aromatic anticonvulsants show cross-reactivity risk; an alternative from a different, non-cross-reactive class should be chosen with specialist input.', 2),
('c3000000-0000-0000-0000-000000000007', 'C', 'Discharge home with a reducing course of oral antihistamines and routine dermatology follow-up', false, 'Ruled out because SJS is a life-threatening emergency requiring urgent admission and specialist care, not outpatient management.', 3),
('c3000000-0000-0000-0000-000000000007', 'D', 'Stop carbamazepine immediately and arrange urgent referral to a specialist dermatology/burns unit', true, 'Correct. This is Stevens-Johnson syndrome; the priority is immediate withdrawal of the culprit drug and urgent specialist input for supportive care, fluid balance, and monitoring.', 4),
('c3000000-0000-0000-0000-000000000007', 'E', 'Start empirical broad-spectrum antibiotics for presumed bacterial sepsis', false, 'Ruled out because the clinical picture is drug-induced SJS, not primarily bacterial sepsis; antibiotics are not the priority intervention.', 5),
('c3000000-0000-0000-0000-000000000008', 'A', 'Discharge with oral antihistamines and dermatology outpatient follow-up in 2 weeks', false, 'Ruled out because TEN is a life-threatening emergency requiring immediate specialist inpatient supportive care, not outpatient management.', 1),
('c3000000-0000-0000-0000-000000000008', 'B', 'Continue co-trimoxazole and add a topical corticosteroid', false, 'Ruled out because continuing the causative drug will worsen the reaction; withdrawal is essential.', 2),
('c3000000-0000-0000-0000-000000000008', 'C', 'Arrange outpatient patch testing to confirm the causative drug before stopping it', false, 'Ruled out because treatment, including drug withdrawal and supportive care, must not be delayed pending confirmatory allergy testing.', 3),
('c3000000-0000-0000-0000-000000000008', 'D', 'Start high-dose intravenous antibiotics for presumed necrotising fasciitis', false, 'Ruled out because the clinical picture, with a recent new drug and mucosal involvement plus Nikolsky-positive widespread epidermal detachment, is consistent with TEN, not necrotising fasciitis.', 4),
('c3000000-0000-0000-0000-000000000008', 'E', 'Urgent admission to a specialist burns or intensive care unit for supportive management', true, 'Correct. This is toxic epidermal necrolysis (over 30% BSA detachment); mortality is high, and patients require the same level of supportive care as major burns (fluid balance, temperature regulation, wound care, infection prevention) alongside stopping the causative drug.', 5),
('c3000000-0000-0000-0000-000000000009', 'A', 'Stevens-Johnson syndrome', false, 'Ruled out because SJS typically features mucocutaneous target lesions and blistering with skin detachment, not the facial oedema, eosinophilia and organ involvement pattern seen here.', 1),
('c3000000-0000-0000-0000-000000000009', 'B', 'Simple morbilliform drug rash', false, 'Ruled out because this does not explain the fever, facial oedema, lymphadenopathy, eosinophilia and hepatic derangement, which indicate a more severe systemic drug reaction.', 2),
('c3000000-0000-0000-0000-000000000009', 'C', 'Drug reaction with eosinophilia and systemic symptoms (DRESS)', true, 'Correct. A delayed onset (2-8 weeks) after starting a high-risk drug such as allopurinol, with fever, facial oedema, lymphadenopathy, eosinophilia and organ involvement (deranged LFTs), is classic for DRESS syndrome.', 3),
('c3000000-0000-0000-0000-000000000009', 'D', 'Acute generalised exanthematous pustulosis (AGEP)', false, 'Ruled out because AGEP is characterised by widespread sterile pustules with rapid onset within days of the culprit drug, not the eosinophilia/organ-involvement pattern seen here.', 4),
('c3000000-0000-0000-0000-000000000009', 'E', 'Infectious mononucleosis', false, 'Ruled out because although this can cause fever, rash and lymphadenopathy, the clear temporal relationship to a high-risk drug and eosinophilia with organ involvement make DRESS far more likely.', 5),
('c3000000-0000-0000-0000-000000000010', 'A', 'Generalised pustular psoriasis', false, 'Ruled out because this typically occurs in a patient with known psoriasis or a strong family history, and lacks such a rapid drug-related onset.', 1),
('c3000000-0000-0000-0000-000000000010', 'B', 'Acute generalised exanthematous pustulosis (AGEP)', true, 'Correct. Rapid onset within days of fever and widespread sterile, non-follicular pustules on an erythematous background after a high-risk drug such as an antibiotic is characteristic of AGEP.', 2),
('c3000000-0000-0000-0000-000000000010', 'C', 'DRESS syndrome', false, 'Ruled out because DRESS usually has a delayed onset of 2-8 weeks, with prominent facial oedema, lymphadenopathy and eosinophilia with organ involvement, rather than a widespread pustular rash within days.', 3),
('c3000000-0000-0000-0000-000000000010', 'D', 'Staphylococcal scalded skin syndrome', false, 'Ruled out because this is caused by exfoliative toxin-producing Staphylococcus aureus, typically in children, causing widespread erythema and skin peeling rather than discrete sterile pustules.', 4),
('c3000000-0000-0000-0000-000000000010', 'E', 'Bacterial folliculitis', false, 'Ruled out because this causes follicular pustules typically localised to hair-bearing areas, not the widespread non-follicular sterile pustulosis with fever seen here.', 5),
('c3000000-0000-0000-0000-000000000011', 'A', 'Stevens-Johnson syndrome', false, 'Ruled out because SJS involves more extensive mucosal erosions, systemic upset, and skin detachment, which are not present in this well patient with minimal mucosal symptoms.', 1),
('c3000000-0000-0000-0000-000000000011', 'B', 'Erythema multiforme (minor)', true, 'Correct. Recurrent herpes simplex virus infection is the most common trigger for erythema multiforme, which classically presents with acral target lesions and minimal or no mucosal involvement in the minor form; it is usually self-limiting.', 2),
('c3000000-0000-0000-0000-000000000011', 'C', 'Toxic epidermal necrolysis', false, 'Ruled out because TEN causes extensive epidermal detachment of over 30% BSA with severe systemic illness, not a limited acral target lesion eruption in an otherwise well patient.', 3),
('c3000000-0000-0000-0000-000000000011', 'D', 'Urticaria', false, 'Ruled out because urticarial wheals are typically transient, each lesion resolving within 24 hours, and blanching, unlike the fixed target lesions described here.', 4),
('c3000000-0000-0000-0000-000000000011', 'E', 'Pityriasis rosea', false, 'Ruled out because pityriasis rosea presents with a herald patch followed by a Christmas-tree distributed eruption on the trunk, not acral target lesions following a herpes simplex infection.', 5),
('c3000000-0000-0000-0000-000000000012', 'A', 'Discharge with emollients and routine dermatology outpatient review in 6 weeks', false, 'Ruled out because erythroderma carries significant risk of systemic complications and requires admission for monitoring and supportive treatment, not outpatient management.', 1),
('c3000000-0000-0000-0000-000000000012', 'B', 'Start empirical antifungal treatment for presumed widespread tinea infection', false, 'Ruled out because the clinical context of psoriasis and abrupt treatment withdrawal points to erythrodermic psoriasis, not a fungal infection.', 2),
('c3000000-0000-0000-0000-000000000012', 'C', 'Restart methotrexate immediately at a higher dose without further assessment', false, 'Ruled out because restarting treatment without addressing the acute systemic instability and without dermatology input is unsafe; supportive care and careful reintroduction of therapy under specialist guidance is required.', 3),
('c3000000-0000-0000-0000-000000000012', 'D', 'Admit to hospital for supportive care, including fluid balance, temperature regulation and monitoring for complications', true, 'Correct. This is erythroderma precipitated by abrupt withdrawal of psoriasis treatment; it is a dermatological emergency due to risks of fluid loss, temperature instability, high-output cardiac failure and secondary infection, requiring hospital admission and supportive care alongside treating the underlying psoriasis.', 4),
('c3000000-0000-0000-0000-000000000012', 'E', 'Reassure the patient this is a normal psoriasis flare and manage with topical treatment alone', false, 'Ruled out because erythroderma affecting over 90% body surface area with systemic upset is a medical emergency, not a simple flare manageable with topical treatment alone.', 5),
('c3000000-0000-0000-0000-000000000013', 'A', 'Start an oral antihistamine as first-line treatment for eczema', false, 'Ruled out because antihistamines are not first-line for eczema itself, though they may occasionally be used for associated sleep disturbance due to itch; emollients and topical steroids are the mainstay.', 1),
('c3000000-0000-0000-0000-000000000013', 'B', 'Refer immediately for patch testing to identify a causative allergen', false, 'Ruled out because typical infantile atopic eczema does not require patch testing as an initial step; this is reserved for suspected allergic contact dermatitis not responding to standard treatment.', 2),
('c3000000-0000-0000-0000-000000000013', 'C', 'Prescribe a potent topical corticosteroid for daily use on the face', false, 'Ruled out because potent steroids are avoided on the face and in infants due to risk of skin atrophy; mild steroids are used for facial/flexural eczema.', 3),
('c3000000-0000-0000-0000-000000000013', 'D', $x$Advise strict elimination of all dairy and wheat from the child's diet$x$, false, 'Ruled out because routine dietary elimination is not recommended as first-line management of eczema without evidence of a specific food allergy driving symptoms.', 4),
('c3000000-0000-0000-0000-000000000013', 'E', 'Switch to a greasier emollient used liberally and frequently, with a mild topical corticosteroid for inflamed areas', true, 'Correct. First-line management of atopic eczema is regular, liberal use of an effective, often greasier, emollient, with a mild topical corticosteroid used for active flares; aqueous cream is now recognised as poorly effective and can be irritant as a leave-on emollient.', 5),
('c3000000-0000-0000-0000-000000000014', 'A', 'Start a topical antifungal cream and review in one week', false, 'Ruled out because the clinical picture of punched-out vesicles and fever on eczematous skin is consistent with herpetic superinfection, not fungal infection.', 1),
('c3000000-0000-0000-0000-000000000014', 'B', 'Increase the potency of his topical corticosteroid to control the flare', false, 'Ruled out because increasing steroid use in the presence of active herpetic infection could worsen viral spread; antiviral treatment is required first.', 2),
('c3000000-0000-0000-0000-000000000014', 'C', 'Start systemic aciclovir and arrange urgent same-day assessment/admission', true, 'Correct. This is eczema herpeticum, a widespread HSV superinfection of eczematous skin, and a dermatological emergency requiring prompt systemic antiviral treatment and urgent specialist assessment, particularly given systemic upset.', 3),
('c3000000-0000-0000-0000-000000000014', 'D', 'Reassure the family this is a typical eczema flare and continue current emollients', false, 'Ruled out because the described features of punched-out vesicles, fever, and rapid spread are not typical of a simple eczema flare and require urgent treatment.', 4),
('c3000000-0000-0000-0000-000000000014', 'E', 'Take a skin swab for bacterial culture and start oral flucloxacillin', false, 'Ruled out because although bacterial superinfection of eczema is common, the described punched-out vesicles and haemorrhagic crusting are characteristic of herpes simplex, requiring antiviral rather than antibiotic treatment.', 5),
('c3000000-0000-0000-0000-000000000015', 'A', 'Patch testing', true, 'Correct. The distribution in contact with metal jewellery strongly suggests allergic contact dermatitis, most commonly to nickel; patch testing identifies the specific contact allergen responsible.', 1),
('c3000000-0000-0000-0000-000000000015', 'B', 'Skin prick testing', false, 'Ruled out because skin prick testing identifies immediate, IgE-mediated type I hypersensitivity allergens such as pollen or food, not the delayed type IV hypersensitivity reaction responsible for allergic contact dermatitis.', 2),
('c3000000-0000-0000-0000-000000000015', 'C', 'Skin biopsy with direct immunofluorescence', false, 'Ruled out because this is used to investigate suspected autoimmune blistering disorders, not localised allergic contact dermatitis.', 3),
('c3000000-0000-0000-0000-000000000015', 'D', 'Total serum IgE level', false, 'Ruled out because this is a non-specific marker sometimes raised in atopic disease, but it does not identify the specific contact allergen and is not the investigation of choice here.', 4),
('c3000000-0000-0000-0000-000000000015', 'E', 'Skin swab for bacterial culture', false, 'Ruled out because there is no clinical suggestion of bacterial infection here; the distribution and chronicity point to an allergic contact reaction.', 5),
('c3000000-0000-0000-0000-000000000016', 'A', 'Start a short course of oral corticosteroids for long-term maintenance treatment', false, 'Ruled out because oral corticosteroids are only used for short-term control of severe flares, not long-term maintenance, due to significant side effects.', 1),
('c3000000-0000-0000-0000-000000000016', 'B', 'Refer for skin prick testing to identify a food allergen trigger', false, 'Ruled out because chronic spontaneous urticaria is rarely driven by a specific identifiable allergen, and routine allergy testing is not recommended as the next step.', 2),
('c3000000-0000-0000-0000-000000000016', 'C', 'Switch to a first-generation sedating antihistamine at standard dose', false, 'Ruled out because first-generation antihistamines are not preferred due to sedative and anticholinergic side effects, and simply switching at standard dose is not the recommended stepwise approach.', 3),
('c3000000-0000-0000-0000-000000000016', 'D', 'Arrange referral for omalizumab as the immediate next step', false, 'Ruled out because omalizumab is reserved for chronic urticaria refractory to updosed antihistamines and other second-line treatments, not as the immediate next step after standard-dose antihistamine failure.', 4),
('c3000000-0000-0000-0000-000000000016', 'E', 'Increase the non-sedating antihistamine to up to four times the standard licensed dose', true, 'Correct. Guidelines for chronic spontaneous urticaria recommend stepping up a non-sedating, second-generation antihistamine to up to fourfold the standard dose before considering other second-line agents.', 5),
('c3000000-0000-0000-0000-000000000017', 'A', 'Give an oral non-sedating antihistamine and observe, with advice to seek emergency care if breathing difficulty or swelling worsens', true, 'Correct. This is acute urticaria with angioedema of the lips but no signs of anaphylaxis, as there is no airway, breathing or circulatory compromise; antihistamines are appropriate first-line treatment with safety-netting advice, reserving intramuscular adrenaline for true anaphylaxis.', 1),
('c3000000-0000-0000-0000-000000000017', 'B', 'Administer intramuscular adrenaline immediately', false, 'Ruled out because there are no features of anaphylaxis, with no respiratory or circulatory compromise; adrenaline is reserved for airway, breathing or circulatory involvement.', 2),
('c3000000-0000-0000-0000-000000000017', 'C', 'Administer intravenous hydrocortisone as first-line treatment', false, 'Ruled out because corticosteroids are not first-line or immediate treatment for isolated urticaria/angioedema without anaphylaxis; antihistamines are preferred initially.', 3),
('c3000000-0000-0000-0000-000000000017', 'D', 'Reassure the patient with no treatment and discharge with no follow-up advice', false, 'Ruled out because although this is not anaphylaxis, ongoing observation and safety-netting advice with treatment for symptomatic relief are appropriate given the allergic trigger and lip swelling.', 4),
('c3000000-0000-0000-0000-000000000017', 'E', 'Arrange elective referral for peanut immunotherapy as the immediate next step', false, 'Ruled out because this is a longer-term specialist allergy consideration, not the immediate management of an acute urticarial/angioedema reaction.', 5),
('c3000000-0000-0000-0000-000000000018', 'A', 'Stop all topical corticosteroid use until the infection has fully resolved', false, 'Ruled out because topical corticosteroid can usually be continued alongside antibiotic treatment to control the underlying eczema, rather than being stopped entirely.', 1),
('c3000000-0000-0000-0000-000000000018', 'B', 'Increase emollient use alone without antibiotics', false, 'Ruled out because the clinical signs of golden crust, weeping, and increased erythema/warmth indicate bacterial superinfection requiring antimicrobial treatment, not emollients alone.', 2),
('c3000000-0000-0000-0000-000000000018', 'C', 'Treat with a short course of oral flucloxacillin alongside continuing emollients and topical corticosteroid', true, 'Correct. Golden-crusted, weeping eczema indicates secondary bacterial infection, most commonly Staphylococcus aureus; localised infected eczema in a systemically well child is usually treated with a short course of oral, or sometimes topical, antibiotics alongside continued eczema treatment.', 3),
('c3000000-0000-0000-0000-000000000018', 'D', 'Arrange urgent hospital admission for intravenous antibiotics', false, 'Ruled out because the child is systemically well with localised signs of infection; oral antibiotics are appropriate rather than admission for IV treatment.', 4),
('c3000000-0000-0000-0000-000000000018', 'E', 'Start a topical antiviral cream for suspected eczema herpeticum', false, 'Ruled out because the description of golden-yellow crust and weeping is characteristic of bacterial superinfection, not the punched-out vesicles typical of eczema herpeticum.', 5),
('c3000000-0000-0000-0000-000000000019', 'A', 'Start oral isotretinoin immediately', false, 'Ruled out because oral isotretinoin is reserved for severe, nodulocystic, or scarring acne, or acne resistant to adequate courses of standard treatment, and requires dermatology specialist initiation; it is not first-line for mild-moderate acne.', 1),
('c3000000-0000-0000-0000-000000000019', 'B', 'Prescribe a combination of a topical retinoid and benzoyl peroxide', true, 'Correct. For mild-to-moderate acne not responding to a single topical agent, first-line escalation is combination topical therapy, such as a topical retinoid plus benzoyl peroxide, or with a topical antibiotic, before considering oral treatment.', 2),
('c3000000-0000-0000-0000-000000000019', 'C', 'Refer urgently to dermatology under the two-week-wait pathway', false, 'Ruled out because acne vulgaris is not a suspected malignancy and does not require urgent cancer referral; routine escalation of topical/oral treatment in primary care is appropriate first.', 3),
('c3000000-0000-0000-0000-000000000019', 'D', 'Reassure her that no treatment is required and acne will resolve on its own', false, 'Ruled out because acne can be safely and effectively treated, and untreated inflammatory acne risks scarring; treatment escalation is appropriate given ongoing symptoms.', 4),
('c3000000-0000-0000-0000-000000000019', 'E', 'Start a combined oral contraceptive pill as the sole first-line treatment for all patients with acne', false, 'Ruled out because although the COCP can help acne in some female patients, it is not the universal first-line step compared with escalating topical therapy in this scenario.', 5),
('c3000000-0000-0000-0000-000000000020', 'A', 'Continue the topical corticosteroid at a lower potency for long-term maintenance', false, 'Ruled out because continued topical steroid use, even at reduced potency, risks worsening rosacea and causing steroid-dependent rebound flares.', 1),
('c3000000-0000-0000-0000-000000000020', 'B', 'Treat as acne vulgaris with a topical retinoid and benzoyl peroxide combination', false, 'Ruled out because the absence of comedones and presence of flushing/telangiectasia points to rosacea rather than acne vulgaris, and benzoyl peroxide can irritate rosacea-prone skin.', 2),
('c3000000-0000-0000-0000-000000000020', 'C', 'Reassure her this is a normal ageing change and no treatment is needed', false, 'Ruled out because rosacea is a treatable inflammatory condition, and the worsening redness related to topical steroid use requires active management.', 3),
('c3000000-0000-0000-0000-000000000020', 'D', 'Stop the topical corticosteroid and start topical treatment such as metronidazole or ivermectin cream', true, 'Correct. This presentation of flushing, telangiectasia, and papulopustules without comedones is rosacea; topical corticosteroids can worsen rosacea and precipitate steroid-induced rosacea, so they should be stopped, with topical metronidazole or ivermectin used as first-line treatment.', 4),
('c3000000-0000-0000-0000-000000000020', 'E', 'Start oral isotretinoin as first-line therapy for rosacea', false, 'Ruled out because oral isotretinoin is a second/third-line option reserved for severe or resistant rosacea, not the initial first-line approach after stopping the aggravating steroid.', 5),
('c3000000-0000-0000-0000-000000000021', 'A', 'Furunculosis (recurrent boils)', false, 'Ruled out because furuncles are typically single follicular abscesses that resolve, rather than the chronic, recurrent, sinus-tract-forming, scarring process described here.', 1),
('c3000000-0000-0000-0000-000000000021', 'B', $x$Bartholin's cyst$x$, false, $x$Ruled out because this is a specific cystic swelling of the Bartholin's gland at the vaginal introitus, not a bilateral, recurrent axillary and groin process.$x$, 2),
('c3000000-0000-0000-0000-000000000021', 'C', 'Hidradenitis suppurativa', true, 'Correct. Recurrent, painful nodules/abscesses with sinus tract formation and scarring in intertriginous areas such as the axillae and groin is characteristic of hidradenitis suppurativa; smoking and obesity are recognised risk factors.', 3),
('c3000000-0000-0000-0000-000000000021', 'D', 'Lymphogranuloma venereum', false, 'Ruled out because this is a sexually transmitted infection causing inguinal lymphadenopathy or buboes, not the chronic bilateral axillary and groin nodules and sinus tracts described, and there is no history suggestive of an STI.', 4),
('c3000000-0000-0000-0000-000000000021', 'E', 'Fox-Fordyce disease', false, 'Ruled out because this rare condition causes itchy papules from apocrine duct occlusion, not painful recurrent abscesses and sinus tracts.', 5),
('c3000000-0000-0000-0000-000000000022', 'A', 'Pseudomonas aeruginosa', true, 'Correct. Hot tub folliculitis is classically caused by Pseudomonas aeruginosa, related to inadequately chlorinated warm water, presenting with follicular papulopustules in areas covered by swimwear, typically 1-4 days after exposure.', 1),
('c3000000-0000-0000-0000-000000000022', 'B', 'Staphylococcus aureus', false, 'Ruled out because although Staphylococcus aureus is the most common cause of folliculitis overall, the specific hot tub exposure history points to Pseudomonas rather than Staphylococcus.', 2),
('c3000000-0000-0000-0000-000000000022', 'C', 'Malassezia furfur', false, 'Ruled out because Malassezia folliculitis is typically associated with occlusion, sweating and antibiotic use, not specifically hot tub exposure.', 3),
('c3000000-0000-0000-0000-000000000022', 'D', 'Herpes simplex virus', false, 'Ruled out because HSV causes grouped vesicles rather than follicular papulopustules, and is not linked to hot tub exposure.', 4),
('c3000000-0000-0000-0000-000000000022', 'E', 'Trichophyton rubrum', false, 'Ruled out because this dermatophyte causes tinea infections with scaling and central clearing, not follicular papulopustules following hot tub use.', 5),
('c3000000-0000-0000-0000-000000000023', 'A', 'Psoriasis', false, 'Ruled out because although psoriasis can affect the scalp, the classic distribution here of nasolabial folds and eyebrows with greasy scale is more typical of seborrhoeic dermatitis; psoriasis plaques are typically thicker with silvery scale on extensor surfaces.', 1),
('c3000000-0000-0000-0000-000000000023', 'B', 'Seborrhoeic dermatitis', true, 'Correct. The distribution involving the scalp, eyebrows, nasolabial folds and retroauricular skin, with erythema and greasy scale, is characteristic of seborrhoeic dermatitis, associated with Malassezia yeast overgrowth; it is more common and often more severe in HIV-positive patients.', 2),
('c3000000-0000-0000-0000-000000000023', 'C', 'Tinea faciei', false, 'Ruled out because tinea faciei typically presents as an annular, scaly plaque with central clearing and an active advancing edge, not the symmetrical scalp/nasolabial/eyebrow distribution described.', 3),
('c3000000-0000-0000-0000-000000000023', 'D', 'Systemic lupus erythematosus (malar rash)', false, 'Ruled out because the malar rash of lupus spares the nasolabial folds and does not typically involve the scalp or retroauricular areas with greasy scale.', 4),
('c3000000-0000-0000-0000-000000000023', 'E', 'Allergic contact dermatitis', false, 'Ruled out because there is no clear contact allergen exposure history, and the classic distribution described is far more consistent with seborrhoeic dermatitis.', 5),
('c3000000-0000-0000-0000-000000000024', 'A', 'Arrange a chest X-ray to exclude pulmonary disease before starting treatment', false, 'Ruled out because this is not a required baseline investigation for isotretinoin; the key safety measures relate to teratogenicity, and liver/lipid monitoring.', 1),
('c3000000-0000-0000-0000-000000000024', 'B', 'Ensure she has stopped all forms of hormonal contraception before starting isotretinoin', false, $x$Ruled out because this is the opposite of correct practice; effective contraception must be maintained, not stopped, due to isotretinoin's teratogenicity.$x$, 2),
('c3000000-0000-0000-0000-000000000024', 'C', 'Check her vitamin D level, as this determines whether isotretinoin can be started', false, 'Ruled out because vitamin D levels are not part of the standard mandatory safety monitoring for isotretinoin; teratogenicity, liver function and lipid monitoring are the priorities.', 3),
('c3000000-0000-0000-0000-000000000024', 'D', 'Confirm she has no history of egg allergy before prescribing', false, 'Ruled out because isotretinoin has no relevant association with egg allergy; this is not a required safety check.', 4),
('c3000000-0000-0000-0000-000000000024', 'E', 'Confirm a negative pregnancy test and ensure effective contraception is established before, during, and for a defined period after treatment', true, 'Correct. Isotretinoin is highly teratogenic; a pregnancy prevention programme, with a negative pregnancy test before starting, effective contraception throughout treatment and for a period afterwards, and regular monitoring, is mandatory for anyone who could become pregnant.', 5),
('c3000000-0000-0000-0000-000000000025', 'A', 'Tinea capitis', false, 'Ruled out because tinea capitis typically causes scaling, broken hairs at varying lengths, and sometimes inflammation or a kerion, rather than a smooth, non-scaly patch with exclamation mark hairs.', 1),
('c3000000-0000-0000-0000-000000000025', 'B', 'Trichotillomania', false, 'Ruled out because this typically shows irregular, patchy hair loss with hairs of varying lengths in a bizarre distribution due to habitual pulling, rather than a single smooth well-demarcated patch.', 2),
('c3000000-0000-0000-0000-000000000025', 'C', 'Scarring (cicatricial) alopecia', false, 'Ruled out because this presents with loss of visible follicular openings and scarring of the underlying skin, unlike the normal-looking scalp skin described here.', 3),
('c3000000-0000-0000-0000-000000000025', 'D', 'Alopecia areata', true, 'Correct. A well-demarcated, smooth patch of non-scarring hair loss with normal underlying scalp and characteristic exclamation mark hairs at the margin is classic for alopecia areata, an autoimmune condition.', 4),
('c3000000-0000-0000-0000-000000000025', 'E', 'Androgenetic alopecia', false, 'Ruled out because this presents as gradual, patterned thinning, typically frontal or vertex in men, rather than a discrete, well-demarcated round patch of complete hair loss.', 5),
('c3000000-0000-0000-0000-000000000026', 'A', 'Oral finasteride with no need for contraceptive precautions as it only affects men', false, 'Ruled out because although finasteride is used off-label in men for androgenetic alopecia, it is teratogenic and crushed or broken tablets must not be handled by women who are or may become pregnant; this is an essential counselling point.', 1),
('c3000000-0000-0000-0000-000000000026', 'B', 'A short course of oral corticosteroids to halt the hair loss', false, 'Ruled out because oral corticosteroids are not a treatment for androgenetic alopecia, which is a hormonally-mediated patterned hair loss, not an inflammatory process requiring steroids.', 2),
('c3000000-0000-0000-0000-000000000026', 'C', 'Reassurance only, as no effective treatments exist for this type of hair loss', false, 'Ruled out because effective treatments, including topical minoxidil and oral finasteride, exist for androgenetic alopecia and should be discussed with the patient.', 3),
('c3000000-0000-0000-0000-000000000026', 'D', 'Topical minoxidil, which can cause an initial temporary increase in shedding when started', true, 'Correct. Topical minoxidil is a first-line, over-the-counter treatment for androgenetic alopecia; patients should be counselled that a temporary increase in shedding can occur in the first few weeks as the hair cycle resets, and continued use is required to maintain benefit.', 4),
('c3000000-0000-0000-0000-000000000026', 'E', 'Urgent dermatology referral, as this presentation requires scalp biopsy to confirm the diagnosis', false, 'Ruled out because androgenetic alopecia with a typical pattern and family history can usually be diagnosed clinically without biopsy or urgent referral.', 5),
('c3000000-0000-0000-0000-000000000027', 'A', 'Prescribe a topical antifungal cream alone', false, 'Ruled out because topical antifungals alone do not adequately penetrate the hair follicle to eradicate tinea capitis; systemic, oral, antifungal treatment is required.', 1),
('c3000000-0000-0000-0000-000000000027', 'B', 'Reassure the family this is alopecia areata and will resolve spontaneously', false, 'Ruled out because the scaling and broken hairs of varying lengths point to a fungal infection rather than alopecia areata, and untreated tinea capitis can spread and cause scarring.', 2),
('c3000000-0000-0000-0000-000000000027', 'C', 'Take hair/skin samples for mycology and start oral antifungal treatment (e.g. griseofulvin or terbinafine)', true, 'Correct. This presentation of scaling, broken hairs of varying lengths, and mild scalp inflammation suggests tinea capitis; oral antifungal treatment is required, as topical antifungals alone are inadequate for this follicular infection, and mycological confirmation guides duration/choice of agent.', 3),
('c3000000-0000-0000-0000-000000000027', 'D', 'Prescribe a potent topical corticosteroid to reduce scalp inflammation', false, 'Ruled out because topical corticosteroids do not treat the underlying fungal infection and may worsen it; antifungal treatment is required.', 4),
('c3000000-0000-0000-0000-000000000027', 'E', 'Advise this is likely due to hair pulling (trichotillomania) and refer for psychological assessment', false, 'Ruled out because the scaling, erythema and broken hairs described are typical of a fungal infection, not the pattern seen in trichotillomania.', 5),
('c3000000-0000-0000-0000-000000000028', 'A', 'Start oral terbinafine empirically without further investigation', false, 'Ruled out because oral antifungal treatment should generally be guided by mycological confirmation given the risk of treating a non-fungal cause and potential drug side effects such as hepatotoxicity.', 1),
('c3000000-0000-0000-0000-000000000028', 'B', 'Arrange a nail biopsy as the first-line investigation', false, 'Ruled out because nail clipping microscopy/culture is the appropriate first-line, non-invasive test for suspected onychomycosis; biopsy is reserved for atypical or diagnostically uncertain cases.', 2),
('c3000000-0000-0000-0000-000000000028', 'C', 'Reassure the patient no treatment is available and offer camouflage advice only', false, $x$Ruled out because effective treatments, including topical or oral antifungals, exist for onychomycosis, and appropriate confirmation and management should be offered given the patient's request for treatment.$x$, 3),
('c3000000-0000-0000-0000-000000000028', 'D', 'Start a topical corticosteroid cream to reduce nail inflammation', false, 'Ruled out because this does not address a fungal infection, and could theoretically worsen it; antifungal treatment guided by confirmation is appropriate.', 4),
('c3000000-0000-0000-0000-000000000028', 'E', 'Send nail clippings for microscopy and culture to confirm fungal infection', true, 'Correct. Before starting systemic antifungal treatment for suspected onychomycosis, mycological confirmation via microscopy and culture of nail clippings is recommended, as other conditions such as psoriasis or trauma can mimic it, and systemic antifungals carry risks that should be justified by a confirmed diagnosis.', 5),
('c3000000-0000-0000-0000-000000000029', 'A', 'Reassure the patient that nail changes are a purely cosmetic feature of psoriasis requiring no further action', false, 'Ruled out because the combination of nail changes and new joint symptoms raises significant concern for psoriatic arthritis, which requires assessment and treatment to prevent joint damage.', 1),
('c3000000-0000-0000-0000-000000000029', 'B', 'Refer to rheumatology for assessment of psoriatic arthritis', true, 'Correct. Nail pitting, onycholysis and subungual hyperkeratosis in a patient with psoriasis are strongly associated with psoriatic arthritis, particularly when accompanied by new joint symptoms such as this distal interphalangeal joint involvement; prompt rheumatology referral is important as early treatment reduces joint damage.', 2),
('c3000000-0000-0000-0000-000000000029', 'C', 'Arrange nail clippings for mycology, as this is most likely onychomycosis', false, 'Ruled out because although onychomycosis can mimic psoriatic nail changes, the combination of typical psoriatic nail signs with new joint symptoms in a known psoriasis patient points strongly to psoriatic arthritis, which should not be missed.', 3),
('c3000000-0000-0000-0000-000000000029', 'D', 'Start a potent topical corticosteroid to the nail folds and review in 6 months', false, 'Ruled out because this does not address the priority concern of possible psoriatic arthritis, which requires timely specialist assessment to prevent irreversible joint damage.', 4),
('c3000000-0000-0000-0000-000000000029', 'E', 'Advise this is unrelated to his psoriasis and likely a separate osteoarthritic process', false, 'Ruled out because in a patient with known psoriasis, new nail changes and distal interphalangeal joint symptoms should first raise suspicion of psoriatic arthritis rather than being dismissed as unrelated.', 5),
('c3000000-0000-0000-0000-000000000030', 'A', 'Topical aluminium chloride antiperspirant', true, 'Correct. Primary focal hyperhidrosis, which is bilateral, symmetrical, and without an identifiable secondary cause, often affecting palms/soles/axillae, is initially managed with topical aluminium chloride preparations, escalating to iontophoresis, botulinum toxin injections or other options if inadequate.', 1),
('c3000000-0000-0000-0000-000000000030', 'B', 'Urgent investigation for an underlying malignancy', false, 'Ruled out because the lifelong, symmetrical, focal pattern without systemic symptoms such as weight loss or night sweats is typical of primary focal hyperhidrosis, not a paraneoplastic or secondary cause requiring urgent malignancy work-up.', 2),
('c3000000-0000-0000-0000-000000000030', 'C', 'Oral beta-blockers as first-line treatment', false, 'Ruled out because beta-blockers are not standard first-line treatment for hyperhidrosis; topical treatments are used first, with other options considered if needed.', 3),
('c3000000-0000-0000-0000-000000000030', 'D', 'Referral for sympathectomy surgery as the first-line option', false, 'Ruled out because surgical sympathectomy is a later-line option reserved for severe, treatment-resistant hyperhidrosis, not the first-line management.', 4),
('c3000000-0000-0000-0000-000000000030', 'E', 'Reassurance only, as no treatments are available for this condition', false, $x$Ruled out because effective stepwise treatments exist for hyperhidrosis, starting with topical antiperspirants, and should be offered given the impact on the patient's daily life.$x$, 5),
('c3000000-0000-0000-0000-000000000031', 'A', 'Treat only the patient, as contacts without symptoms do not require treatment', false, 'Ruled out because scabies is highly contagious with an incubation period before symptoms develop; all close contacts should be treated simultaneously to prevent reinfestation, regardless of current symptoms.', 1),
('c3000000-0000-0000-0000-000000000031', 'B', 'Prescribe a topical corticosteroid alone to control the itching', false, 'Ruled out because this does not treat the underlying infestation; topical steroids may be used for post-scabetic itch after treating the mite infestation with permethrin, not as sole treatment.', 2),
('c3000000-0000-0000-0000-000000000031', 'C', 'Prescribe oral antihistamines alone with no topical treatment', false, 'Ruled out because antihistamines may help symptomatic itch but do not eradicate the mite infestation, which requires topical scabicidal treatment.', 3),
('c3000000-0000-0000-0000-000000000031', 'D', 'Reassure the patient this will resolve spontaneously without treatment', false, 'Ruled out because scabies does not resolve without treatment and is highly contagious; active treatment of the patient and contacts is required.', 4),
('c3000000-0000-0000-0000-000000000031', 'E', 'Treat the patient and all close/household contacts simultaneously with topical permethrin', true, 'Correct. This presentation of nocturnal itch, burrows in finger webs, and an affected close contact is classic for scabies; treatment must include all household/close contacts simultaneously, regardless of symptoms, with topical permethrin, or malathion if permethrin is contraindicated, applied to the whole body, to prevent reinfestation.', 5),
('c3000000-0000-0000-0000-000000000032', 'A', 'Oral flucloxacillin only, with no need to alter school attendance', false, 'Ruled out because although oral antibiotics may be used for more extensive impetigo, localised disease is typically treated topically first, and exclusion advice regarding school/nursery attendance is important due to contagiousness.', 1),
('c3000000-0000-0000-0000-000000000032', 'B', 'Topical fusidic acid (or hydrogen peroxide cream) and advice to avoid school/nursery until lesions are crusted/healed or 48 hours of antibiotic treatment completed', true, 'Correct. This is non-bullous impetigo, typically caused by Staphylococcus aureus or Streptococcus pyogenes; localised disease is treated with topical antibiotics or antiseptic, with exclusion from school/nursery until lesions have crusted over or 48 hours after starting appropriate antibiotic treatment, per local infection control guidance.', 2),
('c3000000-0000-0000-0000-000000000032', 'C', 'Reassure the family this will resolve without treatment and no exclusion advice is needed', false, 'Ruled out because impetigo is contagious and treatment reduces spread and duration; exclusion advice should be given.', 3),
('c3000000-0000-0000-0000-000000000032', 'D', 'Refer urgently to hospital for intravenous antibiotics', false, 'Ruled out because localised impetigo in a well child is managed in primary care with topical treatment; IV antibiotics and admission are not required for this presentation.', 4),
('c3000000-0000-0000-0000-000000000032', 'E', 'Prescribe an oral antifungal cream', false, 'Ruled out because impetigo is a bacterial infection, not fungal, so antifungal treatment would be ineffective.', 5),
('c3000000-0000-0000-0000-000000000033', 'A', 'Admit for intravenous antibiotics, given systemic signs of infection (fever, tachycardia)', true, 'Correct. This is cellulitis with systemic upset; per severity classification such as the Eron classification, the presence of systemic signs of sepsis or significant comorbidity, such as diabetes, generally warrants admission for intravenous antibiotics rather than oral outpatient treatment alone.', 1),
('c3000000-0000-0000-0000-000000000033', 'B', 'Treat with oral flucloxacillin alone as an outpatient with no follow-up arranged', false, 'Ruled out because systemic signs, such as fever and tachycardia, in this diabetic patient indicate more significant cellulitis that warrants admission for IV treatment and monitoring rather than oral outpatient management with no follow-up.', 2),
('c3000000-0000-0000-0000-000000000033', 'C', 'Arrange urgent surgical debridement for suspected necrotising fasciitis', false, 'Ruled out because there are no features here, such as severe pain out of proportion to examination findings, crepitus, or marked systemic toxicity, suggestive of necrotising fasciitis; this is typical cellulitis.', 3),
('c3000000-0000-0000-0000-000000000033', 'D', 'Start topical antibiotic cream to the affected area', false, 'Ruled out because cellulitis is a deeper bacterial skin and soft tissue infection requiring systemic, oral or intravenous, antibiotics, not topical treatment.', 4),
('c3000000-0000-0000-0000-000000000033', 'E', 'Discharge with reassurance and no antibiotic treatment, as this will likely resolve spontaneously', false, 'Ruled out because untreated cellulitis with systemic signs can progress to serious complications such as sepsis; antibiotic treatment and appropriate escalation are required.', 5),
('c3000000-0000-0000-0000-000000000034', 'A', 'Start oral antibiotics and review in the ambulatory care clinic the following day', false, 'Ruled out because this presentation represents a life-threatening surgical emergency requiring immediate admission, resuscitation and urgent surgery, not outpatient oral treatment.', 1),
('c3000000-0000-0000-0000-000000000034', 'B', 'Arrange an outpatient MRI scan to confirm the diagnosis before starting any treatment', false, 'Ruled out because with strong clinical suspicion of necrotising fasciitis and signs of septic shock, treatment must not be delayed awaiting imaging.', 2),
('c3000000-0000-0000-0000-000000000034', 'C', 'Treat as simple cellulitis with oral flucloxacillin and outpatient follow-up', false, 'Ruled out because the combination of disproportionate pain, crepitus and rapid systemic deterioration indicates a much more severe, life-threatening process than simple cellulitis.', 3),
('c3000000-0000-0000-0000-000000000034', 'D', 'Urgent surgical referral for emergency debridement alongside broad-spectrum intravenous antibiotics and aggressive resuscitation', true, 'Correct. Severe pain disproportionate to examination findings, rapidly progressive systemic sepsis, and crepitus are classic features of necrotising fasciitis, a surgical emergency; management requires urgent surgical debridement alongside broad-spectrum IV antibiotics and haemodynamic resuscitation, without delay for imaging if the diagnosis is clinically strongly suspected.', 4),
('c3000000-0000-0000-0000-000000000034', 'E', 'Apply a topical antiseptic dressing and reassess in 24 hours', false, 'Ruled out because this critically unwell patient requires immediate resuscitation and surgical intervention, not delayed reassessment with topical treatment alone.', 5),
('c3000000-0000-0000-0000-000000000035', 'A', 'Topical corticosteroid alone', false, 'Ruled out because topical corticosteroids can worsen and mask fungal infections, a phenomenon known as tinea incognito, even though they may temporarily reduce inflammation and itch.', 1),
('c3000000-0000-0000-0000-000000000035', 'B', 'Oral antibiotics for presumed bacterial cellulitis', false, 'Ruled out because the well-defined annular plaque with central clearing and advancing scaly edge is classic for a fungal infection, not bacterial cellulitis.', 2),
('c3000000-0000-0000-0000-000000000035', 'C', 'Topical antifungal cream (e.g. terbinafine or clotrimazole)', true, 'Correct. This is tinea corporis, a dermatophyte infection classically presenting as an annular scaly plaque with an active advancing edge and central clearing; localised infection is treated with a topical antifungal, with oral antifungals reserved for extensive, resistant or hair-bearing site involvement.', 3),
('c3000000-0000-0000-0000-000000000035', 'D', 'Reassurance only, with no treatment required', false, 'Ruled out because tinea corporis is a treatable and contagious fungal infection, particularly given contact with an animal, a possible source, and should be treated to resolve symptoms and prevent spread.', 4),
('c3000000-0000-0000-0000-000000000035', 'E', 'Oral antiviral treatment', false, 'Ruled out because this presentation is fungal, not viral, so antiviral treatment would be ineffective.', 5),
('c3000000-0000-0000-0000-000000000036', 'A', 'Oral methotrexate as first-line therapy', false, 'Ruled out because systemic treatments like methotrexate are reserved for moderate-to-severe psoriasis not controlled with topical treatment, or with significant impact on quality of life, not as the initial first-line approach.', 1),
('c3000000-0000-0000-0000-000000000036', 'B', 'Phototherapy as the first-line treatment for localised plaques', false, 'Ruled out because phototherapy is typically considered as a second-line option for more widespread psoriasis not responding to topical treatment, not as first-line for this presentation.', 2),
('c3000000-0000-0000-0000-000000000036', 'C', 'Oral antihistamines as first-line therapy', false, 'Ruled out because antihistamines do not address the underlying inflammatory process of psoriasis and are not standard treatment for it.', 3),
('c3000000-0000-0000-0000-000000000036', 'D', 'Reassurance only, as psoriasis does not require active treatment', false, 'Ruled out because chronic plaque psoriasis is a treatable condition, and effective first-line topical therapy should be offered.', 4),
('c3000000-0000-0000-0000-000000000036', 'E', 'Topical vitamin D analogue combined with a potent topical corticosteroid', true, 'Correct. First-line treatment for chronic plaque psoriasis affecting the trunk/limbs is a combination of a topical vitamin D analogue and a potent topical corticosteroid, typically used once daily for up to 4 weeks initially.', 5),
('c3000000-0000-0000-0000-000000000037', 'A', 'Guttate psoriasis', true, 'Correct. Acute onset of numerous small, teardrop-shaped scaly papules on the trunk, typically 2-3 weeks after a streptococcal sore throat, in a child or young adult, is classic for guttate psoriasis.', 1),
('c3000000-0000-0000-0000-000000000037', 'B', 'Pityriasis rosea', false, 'Ruled out because pityriasis rosea typically begins with a single herald patch followed by a Christmas tree distributed eruption, and is not specifically preceded by a streptococcal sore throat.', 2),
('c3000000-0000-0000-0000-000000000037', 'C', 'Chronic plaque psoriasis', false, 'Ruled out because chronic plaque psoriasis presents with larger, well-demarcated, thicker plaques typically on extensor surfaces, not the widespread small teardrop lesions with an acute post-streptococcal onset described here.', 3),
('c3000000-0000-0000-0000-000000000037', 'D', 'Viral exanthem', false, 'Ruled out because the described morphology of teardrop scaly papules and the temporal link to streptococcal sore throat are specific for guttate psoriasis, not a nonspecific viral rash.', 4),
('c3000000-0000-0000-0000-000000000037', 'E', 'Secondary syphilis', false, 'Ruled out because although secondary syphilis can cause a widespread rash, it does not typically present with this teardrop, scaly morphology following a sore throat, and there is no risk history to suggest this diagnosis.', 5),
('c3000000-0000-0000-0000-000000000038', 'A', 'Reassure her that joint symptoms are unrelated to her psoriasis and require no further action', false, 'Ruled out because dactylitis and enthesitis in a psoriasis patient are classic features of psoriatic arthritis and should not be dismissed as unrelated.', 1),
('c3000000-0000-0000-0000-000000000038', 'B', 'Start a potent topical corticosteroid for her skin psoriasis and review in 6 months', false, 'Ruled out because this does not address the priority issue of possible psoriatic arthritis, which requires timely specialist assessment and disease-modifying treatment to prevent joint damage.', 2),
('c3000000-0000-0000-0000-000000000038', 'C', 'Arrange an urgent same-day referral to the emergency department', false, 'Ruled out because although prompt outpatient rheumatology referral is important, this presentation with subacute joint symptoms is not itself an emergency requiring emergency department attendance.', 3),
('c3000000-0000-0000-0000-000000000038', 'D', 'Refer to rheumatology for assessment and treatment of suspected psoriatic arthritis', true, 'Correct. Dactylitis, described as a sausage digit, and enthesitis, such as this heel pain from Achilles tendon insertion, in a patient with psoriasis are highly suggestive of psoriatic arthritis; prompt rheumatology referral is important, as early treatment reduces the risk of irreversible joint damage.', 4),
('c3000000-0000-0000-0000-000000000038', 'E', 'Advise this is likely rheumatoid arthritis and start empirical methotrexate in primary care', false, 'Ruled out because the pattern described, with dactylitis and enthesitis in a psoriasis patient, is classic for psoriatic rather than rheumatoid arthritis, and initiating disease-modifying treatment should be led by specialist rheumatology assessment, not started empirically in primary care.', 5),
('c3000000-0000-0000-0000-000000000039', 'A', 'Guttate psoriasis', false, 'Ruled out because guttate psoriasis presents with numerous small teardrop lesions typically following a streptococcal sore throat, without the classic herald patch and Christmas-tree distribution described here.', 1),
('c3000000-0000-0000-0000-000000000039', 'B', 'Tinea corporis', false, 'Ruled out because tinea corporis presents as one or a few annular plaques with an active advancing edge and central clearing, not this widespread symmetrical eruption with a preceding herald patch.', 2),
('c3000000-0000-0000-0000-000000000039', 'C', 'Pityriasis rosea', true, 'Correct. The classic pattern of a single herald patch followed by a widespread Christmas tree distributed eruption along skin cleavage lines is characteristic of pityriasis rosea, thought to be associated with reactivation of human herpesviruses 6/7; it is generally self-limiting over 6-12 weeks.', 3),
('c3000000-0000-0000-0000-000000000039', 'D', 'Secondary syphilis', false, 'Ruled out because although secondary syphilis can mimic pityriasis rosea, the absence of risk factors and the classic herald patch/Christmas tree pattern here make pityriasis rosea far more likely; syphilis serology may still be considered if risk factors are present or palms/soles are involved.', 4),
('c3000000-0000-0000-0000-000000000039', 'E', 'Nummular eczema', false, 'Ruled out because nummular eczema presents with itchy, coin-shaped eczematous plaques, without the classic herald patch and evolving Christmas tree distribution described here.', 5),
('c3000000-0000-0000-0000-000000000040', 'A', 'Psoriasis', false, $x$Ruled out because psoriasis plaques are typically erythematous with silvery scale on extensor surfaces, not violaceous flat-topped papules with Wickham's striae on flexor surfaces.$x$, 1),
('c3000000-0000-0000-0000-000000000040', 'B', 'Lichen planus', true, $x$Correct. Violaceous, flat-topped, polygonal, pruritic papules with Wickham's striae (fine white lines) on the wrists, plus oral white streaky lesions, are classic for lichen planus; certain drugs, including thiazide diuretics, can trigger a lichenoid drug eruption, so recent medication changes should be reviewed.$x$, 2),
('c3000000-0000-0000-0000-000000000040', 'C', 'Pityriasis rosea', false, $x$Ruled out because pityriasis rosea presents with a herald patch and Christmas-tree distributed oval lesions, not violaceous polygonal papules with Wickham's striae and oral involvement.$x$, 3),
('c3000000-0000-0000-0000-000000000040', 'D', 'Discoid lupus erythematosus', false, $x$Ruled out because discoid lupus typically causes scaly, scarring, erythematous plaques often on sun-exposed skin such as the face and scalp, not the violaceous polygonal wrist papules with Wickham's striae described here.$x$, 4),
('c3000000-0000-0000-0000-000000000040', 'E', 'Allergic contact dermatitis', false, $x$Ruled out because contact dermatitis typically presents as eczematous change, such as erythema, vesicles, and scaling, at a site of allergen contact, not the violaceous polygonal papules with Wickham's striae and mucosal involvement seen here.$x$, 5),
('c3000000-0000-0000-0000-000000000041', 'A', 'Urgent 2-week-wait referral, as this lesion has a high risk of metastasis', false, 'Ruled out because BCC very rarely metastasises; while it should be treated, usually surgically, due to local tissue invasion, it does not require the same urgent cancer pathway used for lesions with high metastatic potential.', 1),
('c3000000-0000-0000-0000-000000000041', 'B', 'Reassurance only, as this is a benign lesion requiring no treatment', false, 'Ruled out because although BCC has a good prognosis, it is a malignant skin cancer that requires treatment, typically excision, to prevent progressive local tissue destruction.', 2),
('c3000000-0000-0000-0000-000000000041', 'C', 'Topical emollient and review in 12 months', false, 'Ruled out because this is a malignant lesion requiring active treatment, not simple emollient use and delayed review.', 3),
('c3000000-0000-0000-0000-000000000041', 'D', 'Routine referral to dermatology for likely surgical excision', true, 'Correct. This is a classic presentation of basal cell carcinoma, with a pearly nodule with telangiectasia, slow growth, and a sun-exposed site; BCC is locally invasive but very rarely metastasises, so routine, rather than urgent two-week-wait, dermatology referral for excision or other treatment is appropriate.', 4),
('c3000000-0000-0000-0000-000000000041', 'E', 'Oral antibiotics for presumed infected sebaceous cyst', false, 'Ruled out because the described features of a pearly nodule, telangiectasia, slow growth, and ulceration are characteristic of BCC, not an infected cyst.', 5),
('c3000000-0000-0000-0000-000000000042', 'A', 'Routine dermatology referral, as this is almost certainly a benign keratoacanthoma', false, 'Ruled out because while keratoacanthoma is a differential and can be difficult to distinguish clinically from SCC, the rapid growth, immunosuppression, and clinical suspicion of malignancy warrant urgent referral rather than routine reassurance, since SCC cannot be safely excluded clinically.', 1),
('c3000000-0000-0000-0000-000000000042', 'B', 'Urgent (2-week-wait) referral to dermatology for suspected squamous cell carcinoma', true, 'Correct. A rapidly growing, tender, hyperkeratotic, ulcerating nodule in an immunosuppressed patient is highly suspicious for squamous cell carcinoma, which has a meaningful risk of metastasis, higher than BCC; urgent two-week-wait referral is indicated for suspected SCC.', 2),
('c3000000-0000-0000-0000-000000000042', 'C', 'Reassurance and review in primary care in 3 months', false, 'Ruled out because a rapidly growing, ulcerating lesion in an immunosuppressed patient requires urgent specialist assessment, not delayed review.', 3),
('c3000000-0000-0000-0000-000000000042', 'D', 'Topical 5-fluorouracil cream as first-line treatment without specialist referral', false, 'Ruled out because topical treatment is used for precursor lesions like actinic keratosis, not for a lesion with this clinical suspicion of invasive SCC, which requires urgent specialist assessment and likely surgical treatment.', 4),
('c3000000-0000-0000-0000-000000000042', 'E', 'Oral antibiotics for a presumed infected wound', false, 'Ruled out because the description of a hyperkeratotic, rapidly growing, ulcerating nodule is not consistent with a simple infected wound and raises strong suspicion of skin malignancy requiring urgent referral.', 5),
('c3000000-0000-0000-0000-000000000043', 'A', 'Reassurance, as the lesion is not bleeding or itching and these features indicate a benign process', false, 'Ruled out because the absence of bleeding or itching does not exclude melanoma; the described ABCDE features are concerning and warrant urgent referral regardless.', 1),
('c3000000-0000-0000-0000-000000000043', 'B', 'Routine dermatology referral in 6 weeks, as this is not an urgent presentation', false, 'Ruled out because a lesion with suspicious ABCDE features requires urgent two-week-wait referral, not routine referral, given the risk of melanoma and the importance of early diagnosis for prognosis.', 2),
('c3000000-0000-0000-0000-000000000043', 'C', 'Urgent (2-week-wait) referral to a pigmented lesion/dermatology clinic for suspected melanoma', true, 'Correct. Asymmetry, irregular border, colour variation, and change in a pigmented lesion, features captured by the ABCDE criteria, raise strong suspicion of melanoma, which requires urgent two-week-wait referral for specialist assessment and likely excision biopsy.', 3),
('c3000000-0000-0000-0000-000000000043', 'D', 'Arrange shave biopsy in primary care to establish the diagnosis before referral', false, 'Ruled out because shave biopsy is inappropriate for a suspected melanoma, as it can compromise accurate assessment of tumour (Breslow) thickness; excision biopsy should be performed by or after specialist assessment.', 4),
('c3000000-0000-0000-0000-000000000043', 'E', 'Advise use of a topical retinoid cream to the lesion and review in 3 months', false, 'Ruled out because a suspicious pigmented lesion should not be treated topically while awaiting delayed review; urgent referral is required.', 5),
('c3000000-0000-0000-0000-000000000044', 'A', 'Refer urgently for assessment, as thickening/induration in a previously stable actinic keratosis raises concern for transformation to squamous cell carcinoma', true, 'Correct. Actinic keratoses are premalignant lesions with a small but real risk of progression to SCC; a lesion that becomes thicker, tender, indurated or rapidly changing should raise suspicion of malignant transformation and be assessed urgently rather than treated as routine actinic keratosis.', 1),
('c3000000-0000-0000-0000-000000000044', 'B', 'Treat all lesions, including the changed one, with topical fluorouracil cream without further assessment', false, 'Ruled out because a lesion showing signs of possible transformation to SCC should be assessed and likely biopsied before topical field treatment, which is appropriate for stable, uncomplicated actinic keratoses but not a lesion with concerning change.', 2),
('c3000000-0000-0000-0000-000000000044', 'C', 'Reassure the patient that actinic keratoses never progress to skin cancer', false, 'Ruled out because actinic keratoses do carry a small risk of progression to squamous cell carcinoma, and a changing lesion should not be dismissed.', 3),
('c3000000-0000-0000-0000-000000000044', 'D', 'Treat only with sun protection advice, as actinic keratoses require no active treatment', false, 'Ruled out because although sun protection is important, a changing lesion requires further assessment for possible malignant transformation, not observation alone.', 4),
('c3000000-0000-0000-0000-000000000044', 'E', 'Arrange cryotherapy to the changed lesion in primary care without further referral', false, 'Ruled out because a lesion with features suggestive of transformation should be assessed, and typically biopsied, by a specialist before destructive treatment, to avoid missing an early SCC.', 5),
('c3000000-0000-0000-0000-000000000045', 'A', 'Malignant melanoma', false, 'Ruled out because the long-standing, unchanged, stuck-on appearance with a benign warty surface is not consistent with melanoma, which typically shows asymmetry, irregular borders and colour variation with a history of change.', 1),
('c3000000-0000-0000-0000-000000000045', 'B', 'Basal cell carcinoma', false, 'Ruled out because BCC typically presents as a pearly nodule with telangiectasia, often with ulceration, rather than a warty stuck-on plaque.', 2),
('c3000000-0000-0000-0000-000000000045', 'C', 'Squamous cell carcinoma', false, 'Ruled out because SCC typically presents as a hyperkeratotic, tender, ulcerating, and often rapidly growing lesion, unlike this stable, long-standing benign-appearing lesion.', 3),
('c3000000-0000-0000-0000-000000000045', 'D', 'Dysplastic naevus', false, 'Ruled out because dysplastic naevi are pigmented moles with some atypical features but not the classic greasy, warty, stuck-on appearance of a seborrhoeic keratosis.', 4),
('c3000000-0000-0000-0000-000000000045', 'E', 'Seborrhoeic keratosis', true, 'Correct. A well-demarcated, brown, warty, stuck-on appearing plaque, often multiple and long-standing/unchanged, is characteristic of a seborrhoeic keratosis, a common benign skin lesion.', 5),
('c3000000-0000-0000-0000-000000000046', 'A', 'Osteoarthritis', false, 'Ruled out because osteoarthritis is a degenerative joint condition and is not a recognised cause of erythema nodosum.', 1),
('c3000000-0000-0000-0000-000000000046', 'B', 'Streptococcal infection', true, 'Correct. Erythema nodosum, with tender nodules on the shins and often systemic symptoms, commonly follows streptococcal throat infection, alongside other causes including sarcoidosis, inflammatory bowel disease, tuberculosis, and certain drugs; a focused history and examination, and investigations such as throat swab/ASOT, chest X-ray, and inflammatory markers, should look for an underlying cause.', 2),
('c3000000-0000-0000-0000-000000000046', 'C', 'Iron deficiency anaemia', false, 'Ruled out because iron deficiency anaemia is not a recognised trigger for erythema nodosum.', 3),
('c3000000-0000-0000-0000-000000000046', 'D', 'Hypothyroidism', false, 'Ruled out because hypothyroidism is not a recognised cause of erythema nodosum.', 4),
('c3000000-0000-0000-0000-000000000046', 'E', 'Vitamin D deficiency', false, 'Ruled out because vitamin D deficiency is not an established cause of erythema nodosum.', 5),
('c3000000-0000-0000-0000-000000000047', 'A', 'Cellulitis', false, 'Ruled out because cellulitis would be expected to show bacterial growth on swab and typically responds to antibiotics, unlike this progressively enlarging, sterile, antibiotic-unresponsive ulcer.', 1),
('c3000000-0000-0000-0000-000000000047', 'B', 'Venous leg ulcer', false, 'Ruled out because venous ulcers typically occur over the medial malleolus in the context of venous insufficiency, with a more gradual onset, not this rapidly progressive, violaceous-bordered ulcer.', 2),
('c3000000-0000-0000-0000-000000000047', 'C', 'Necrotising fasciitis', false, 'Ruled out because although this is also rapidly progressive, necrotising fasciitis presents with severe systemic toxicity and pain out of proportion, and the described chronic disease association with IBD, violaceous undermined border and sterile culture point instead to pyoderma gangrenosum.', 3),
('c3000000-0000-0000-0000-000000000047', 'D', 'Squamous cell carcinoma', false, 'Ruled out because SCC typically presents as a slower-growing, hyperkeratotic, ulcerating nodule, not a rapidly enlarging ulcer with a violaceous undermined border in the context of underlying IBD.', 4),
('c3000000-0000-0000-0000-000000000047', 'E', 'Pyoderma gangrenosum', true, 'Correct. A rapidly progressive, painful ulcer with a violaceous, undermined border, sterile on culture, and unresponsive to antibiotics, in a patient with inflammatory bowel disease, is characteristic of pyoderma gangrenosum, a neutrophilic dermatosis associated with IBD.', 5),
('c3000000-0000-0000-0000-000000000048', 'A', 'Erythema nodosum', false, 'Ruled out because erythema nodosum presents as tender, erythematous nodules rather than yellow-brown atrophic plaques with telangiectasia.', 1),
('c3000000-0000-0000-0000-000000000048', 'B', 'Pretibial myxoedema', false, $x$Ruled out because pretibial myxoedema, associated with Graves' disease, typically presents as waxy, indurated, non-pitting plaques/nodules rather than the yellow-brown atrophic, telangiectatic appearance described here, and there is no history of thyroid disease.$x$, 2),
('c3000000-0000-0000-0000-000000000048', 'C', 'Necrobiosis lipoidica', true, 'Correct. Well-demarcated, yellow-brown, atrophic plaques with telangiectasia on the shins in a patient with diabetes mellitus, typically type 1, are characteristic of necrobiosis lipoidica.', 3),
('c3000000-0000-0000-0000-000000000048', 'D', 'Venous stasis dermatitis', false, 'Ruled out because venous stasis dermatitis typically presents with erythema, scaling, and hyperpigmentation in the context of chronic venous insufficiency, not the well-demarcated yellow-brown atrophic plaques described.', 4),
('c3000000-0000-0000-0000-000000000048', 'E', 'Lichen sclerosus', false, 'Ruled out because lichen sclerosus classically affects the anogenital skin with white atrophic plaques, not the shins, and is not associated with diabetes in the way described.', 5),
('c3000000-0000-0000-0000-000000000049', 'A', 'Investigate for an underlying occult malignancy (e.g. gastric adenocarcinoma)', true, 'Correct. Acanthosis nigricans is most commonly associated with insulin resistance/obesity, but rapid-onset acanthosis nigricans in an older, non-obese patient, especially with unintentional weight loss, is a red flag for malignant acanthosis nigricans, classically associated with gastrointestinal, particularly gastric, adenocarcinoma, and warrants prompt investigation.', 1),
('c3000000-0000-0000-0000-000000000049', 'B', 'Reassure the patient this is a benign skin change related to ageing', false, 'Ruled out because the rapid onset and associated systemic features of weight loss in a non-obese, non-diabetic patient raise significant concern for an underlying malignancy, which must not be dismissed as benign ageing change.', 2),
('c3000000-0000-0000-0000-000000000049', 'C', 'Check HbA1c only and reassure if normal, with no further action', false, 'Ruled out because although insulin resistance/diabetes should be excluded, the atypical rapid onset with weight loss requires broader investigation for occult malignancy, not reassurance if glucose testing is normal.', 3),
('c3000000-0000-0000-0000-000000000049', 'D', 'Start a topical retinoid cream for cosmetic improvement and review in 6 months', false, 'Ruled out because addressing the underlying cause, particularly ruling out malignancy, is the priority; symptomatic skin treatment without investigation risks missing a serious underlying diagnosis.', 4),
('c3000000-0000-0000-0000-000000000049', 'E', 'Refer for bariatric surgery assessment, as this is likely due to obesity', false, 'Ruled out because the patient has no history of obesity, and the clinical picture of rapid onset and weight loss is atypical for the common obesity/insulin-resistance-associated form of acanthosis nigricans.', 5),
('c3000000-0000-0000-0000-000000000050', 'A', 'Reassure the patient this is a benign age-related skin change requiring no further investigation', false, 'Ruled out because this presentation, with raised CK and characteristic rash, represents a significant systemic autoimmune condition, dermatomyositis, with an important malignancy association, not a benign skin change.', 1),
('c3000000-0000-0000-0000-000000000050', 'B', 'Start a topical corticosteroid for the rash alone, with no further systemic investigation', false, 'Ruled out because dermatomyositis is a systemic condition requiring assessment of muscle involvement, specialist input, and malignancy screening, not just topical treatment of the skin findings.', 2),
('c3000000-0000-0000-0000-000000000050', 'C', 'Arrange nerve conduction studies as the key next investigation', false, 'Ruled out because the clinical picture points to a myopathic process, with proximal weakness and raised CK, and characteristic skin findings, rather than a peripheral nerve disorder that nerve conduction studies would primarily assess.', 3),
('c3000000-0000-0000-0000-000000000050', 'D', 'Investigate for an underlying occult malignancy, alongside referral for specialist rheumatological/dermatological management', true, $x$Correct. The combination of proximal muscle weakness, a heliotrope rash of violaceous eyelid discolouration, Gottron's papules over the knuckles, and raised creatine kinase is classic for dermatomyositis; in adults, particularly older patients, dermatomyositis is associated with an increased risk of underlying malignancy, so age-appropriate malignancy screening is an important part of management alongside specialist treatment.$x$, 4),
('c3000000-0000-0000-0000-000000000050', 'E', 'Treat as simple contact dermatitis with allergen avoidance advice', false, $x$Ruled out because the described rash of heliotrope discolouration and Gottron's papules, combined with proximal muscle weakness and raised CK, is not consistent with contact dermatitis, and dismissing it as such would miss dermatomyositis and its malignancy association.$x$, 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('c3000000-0000-0000-0000-000000000001', $x$Bullous pemphigoid classically affects the elderly, causing pruritus preceding tense, subepidermal bullae with a negative Nikolsky's sign.$x$, 1),
('c3000000-0000-0000-0000-000000000001', 'Direct immunofluorescence shows linear IgG and C3 deposition along the basement membrane zone.', 2),
('c3000000-0000-0000-0000-000000000001', 'Mucosal involvement is uncommon in bullous pemphigoid, unlike pemphigus vulgaris.', 3),
('c3000000-0000-0000-0000-000000000002', 'Pemphigus vulgaris often presents with painful oral erosions before skin involvement, reflecting desmoglein 3 predominance in mucosa.', 1),
('c3000000-0000-0000-0000-000000000002', $x$Nikolsky's sign (shearing of apparently normal epidermis under lateral pressure) is positive in pemphigus, reflecting intraepidermal (acantholytic) blister formation.$x$, 2),
('c3000000-0000-0000-0000-000000000002', 'Direct immunofluorescence in pemphigus vulgaris shows intercellular IgG deposition in a chicken-wire pattern.', 3),
('c3000000-0000-0000-0000-000000000003', 'Dermatitis herpetiformis is caused by IgA autoantibodies against epidermal transglutaminase and is strongly linked to coeliac disease.', 1),
('c3000000-0000-0000-0000-000000000003', 'Typical distribution is symmetrical over extensor surfaces (elbows, knees, buttocks, scalp).', 2),
('c3000000-0000-0000-0000-000000000003', 'First-line treatment is a strict gluten-free diet; dapsone gives rapid symptomatic relief while dietary changes take effect.', 3),
('c3000000-0000-0000-0000-000000000004', 'Pemphigoid gestationis classically begins periumbilically in the third trimester and progresses to widespread tense blisters.', 1),
('c3000000-0000-0000-0000-000000000004', 'Direct immunofluorescence showing linear C3 (with or without IgG) along the basement membrane zone differentiates it from other pregnancy dermatoses, which are DIF-negative.', 2),
('c3000000-0000-0000-0000-000000000004', 'It is associated with a small increase in risk of prematurity and low birth weight, so obstetric input alongside dermatology is required.', 3),
('c3000000-0000-0000-0000-000000000005', $x$Linear IgG/C3 at the basement membrane zone with a negative Nikolsky's sign indicates a subepidermal blistering disorder (bullous pemphigoid).$x$, 1),
('c3000000-0000-0000-0000-000000000005', $x$Intercellular (chicken-wire) IgG deposition with a positive Nikolsky's sign indicates an intraepidermal, acantholytic blistering disorder (pemphigus vulgaris).$x$, 2),
('c3000000-0000-0000-0000-000000000005', $x$Nikolsky's sign is positive when blisters form within the epidermis (fragile roof) and negative when the split is below the epidermis (intact roof).$x$, 3),
('c3000000-0000-0000-0000-000000000006', 'DPP-4 inhibitors (gliptins) are an established, increasingly recognised trigger for drug-induced bullous pemphigoid.', 1),
('c3000000-0000-0000-0000-000000000006', 'Management involves withdrawing the likely causative drug where possible, alongside dermatological treatment of the blistering disease.', 2),
('c3000000-0000-0000-0000-000000000006', 'Always consider a drug cause in new-onset bullous pemphigoid, particularly with a temporal relationship to a new medication.', 3),
('c3000000-0000-0000-0000-000000000007', 'Stevens-Johnson syndrome (SJS) affects less than 10% body surface area with skin detachment; toxic epidermal necrolysis (TEN) affects more than 30%, with 10-30% termed SJS/TEN overlap.', 1),
('c3000000-0000-0000-0000-000000000007', 'The single most important management step in drug-induced SJS/TEN is immediate withdrawal of the causative drug, alongside urgent specialist (burns/dermatology) supportive care.', 2),
('c3000000-0000-0000-0000-000000000007', 'Common culprits include anticonvulsants (especially aromatic ones like carbamazepine, phenytoin, lamotrigine), allopurinol, and sulfonamide antibiotics.', 3),
('c3000000-0000-0000-0000-000000000008', 'TEN involves more than 30% body surface area epidermal detachment and carries a high mortality; it is managed like a major burn in a specialist unit.', 1),
('c3000000-0000-0000-0000-000000000008', 'Sulfonamide antibiotics (e.g. co-trimoxazole), allopurinol, and aromatic anticonvulsants are classic culprits for SJS/TEN.', 2),
('c3000000-0000-0000-0000-000000000008', 'SCORTEN scoring can be used to estimate prognosis and guide the level of care required.', 3),
('c3000000-0000-0000-0000-000000000009', 'DRESS typically develops 2-8 weeks after starting the causative drug (classically allopurinol, anticonvulsants, or sulfonamides), unlike the more rapid onset of AGEP or SJS/TEN.', 1),
('c3000000-0000-0000-0000-000000000009', 'Key features are fever, facial oedema, lymphadenopathy, eosinophilia, and internal organ involvement (commonly hepatic).', 2),
('c3000000-0000-0000-0000-000000000009', 'The causative drug must be stopped immediately; internal organ involvement can progress and be fatal even after drug withdrawal, so ongoing monitoring is essential.', 3),
('c3000000-0000-0000-0000-000000000010', 'AGEP presents with rapid-onset fever and widespread sterile, non-follicular pustules, typically 1-2 days after the causative drug (commonly antibiotics).', 1),
('c3000000-0000-0000-0000-000000000010', 'It is usually self-limiting once the drug is withdrawn, unlike generalised pustular psoriasis, which tends to relapse and is linked to a personal/family history of psoriasis.', 2),
('c3000000-0000-0000-0000-000000000010', 'Distinguishing AGEP from generalised pustular psoriasis and bacterial infection guides appropriate drug withdrawal versus continued treatment.', 3),
('c3000000-0000-0000-0000-000000000011', 'Erythema multiforme is most commonly triggered by herpes simplex virus infection and classically presents with acral target lesions.', 1),
('c3000000-0000-0000-0000-000000000011', 'Erythema multiforme minor has minimal or no mucosal involvement and is self-limiting, in contrast to erythema multiforme major and SJS/TEN, which involve significant mucosal disease and systemic illness.', 2),
('c3000000-0000-0000-0000-000000000011', 'Recurrent HSV-associated erythema multiforme may warrant prophylactic aciclovir if episodes are frequent.', 3),
('c3000000-0000-0000-0000-000000000012', 'Erythroderma (exfoliative dermatitis, over 90% body surface area erythema) is a dermatological emergency, often precipitated by abrupt withdrawal of systemic treatment for psoriasis, drug reactions, or underlying eczema/lymphoma.', 1),
('c3000000-0000-0000-0000-000000000012', 'Complications include temperature instability, high-output cardiac failure, fluid and electrolyte imbalance, and secondary sepsis, necessitating hospital admission.', 2),
('c3000000-0000-0000-0000-000000000012', 'Management involves supportive care alongside cautious reintroduction of treatment for the underlying skin disease, with dermatology input.', 3),
('c3000000-0000-0000-0000-000000000013', 'First-line management of atopic eczema is regular liberal emollient use plus topical corticosteroids matched in potency to disease severity and site, with mild potency used for face/flexures.', 1),
('c3000000-0000-0000-0000-000000000013', 'Aqueous cream is not recommended as a leave-on emollient due to poor efficacy and risk of skin irritation.', 2),
('c3000000-0000-0000-0000-000000000013', 'Potent topical steroids should be avoided on the face and in young infants due to the risk of skin atrophy.', 3),
('c3000000-0000-0000-0000-000000000014', 'Eczema herpeticum presents with monomorphic punched-out vesicles/erosions with haemorrhagic crusting on a background of eczema, often with fever and malaise.', 1),
('c3000000-0000-0000-0000-000000000014', 'It is a dermatological emergency requiring prompt systemic aciclovir and urgent specialist assessment, especially with periocular involvement or systemic illness.', 2),
('c3000000-0000-0000-0000-000000000014', 'It should be distinguished from bacterial superinfection of eczema, which causes weeping, crusted, honey-coloured lesions rather than punched-out vesicles.', 3),
('c3000000-0000-0000-0000-000000000015', 'Allergic contact dermatitis is a delayed, type IV, T-cell mediated hypersensitivity reaction, confirmed with patch testing rather than skin prick testing.', 1),
('c3000000-0000-0000-0000-000000000015', 'Nickel, found in jewellery, watch straps, and clothing fasteners, is one of the most common causes of allergic contact dermatitis.', 2),
('c3000000-0000-0000-0000-000000000015', 'Management involves identifying and avoiding the causative allergen alongside standard eczema treatment (emollients, topical steroids) for symptomatic relief.', 3),
('c3000000-0000-0000-0000-000000000016', 'Chronic urticaria is defined as recurrent wheals, with or without angioedema, occurring for more than 6 weeks, most commonly chronic spontaneous urticaria with no identifiable trigger.', 1),
('c3000000-0000-0000-0000-000000000016', 'Stepwise management starts with a non-sedating antihistamine, updosed up to fourfold before adding other agents.', 2),
('c3000000-0000-0000-0000-000000000016', 'Omalizumab and ciclosporin are reserved for antihistamine-refractory chronic urticaria and require specialist input.', 3),
('c3000000-0000-0000-0000-000000000017', 'Anaphylaxis is defined by airway, breathing or circulatory compromise; isolated urticaria and angioedema without these features should be treated with antihistamines, not adrenaline.', 1),
('c3000000-0000-0000-0000-000000000017', 'Intramuscular adrenaline is reserved for true anaphylaxis and should not be given for uncomplicated urticaria/angioedema.', 2),
('c3000000-0000-0000-0000-000000000017', 'All patients with a suspected significant allergic reaction should be given safety-netting advice and considered for specialist allergy referral to identify triggers and provide an emergency plan.', 3),
('c3000000-0000-0000-0000-000000000018', 'Secondary bacterial infection of eczema, typically Staphylococcus aureus, presents with weeping, golden-yellow crusting and increased erythema/warmth.', 1),
('c3000000-0000-0000-0000-000000000018', 'Localised infected eczema in a systemically well patient is generally managed with a short course of oral or topical antibiotics alongside continued eczema treatment.', 2),
('c3000000-0000-0000-0000-000000000018', 'This should be distinguished from eczema herpeticum, which presents with monomorphic punched-out vesicles and systemic upset, requiring antivirals rather than antibiotics.', 3),
('c3000000-0000-0000-0000-000000000019', 'Stepwise acne management starts with topical treatments such as a retinoid or benzoyl peroxide alone, then combination topical therapy, before considering oral antibiotics or hormonal treatment, with oral isotretinoin reserved for severe/scarring/resistant disease.', 1),
('c3000000-0000-0000-0000-000000000019', 'Topical retinoids are teratogenic and require contraceptive advice in women of childbearing potential.', 2),
('c3000000-0000-0000-0000-000000000019', 'Referral to dermatology is indicated for severe nodulocystic acne, scarring, or acne not responding to optimised primary care treatment.', 3),
('c3000000-0000-0000-0000-000000000020', 'Rosacea presents with facial flushing, persistent erythema, telangiectasia and papulopustules, but without comedones, distinguishing it from acne vulgaris.', 1),
('c3000000-0000-0000-0000-000000000020', 'Topical corticosteroids should be avoided in rosacea as they can worsen the condition or precipitate rosacea fulminans; if already used, they should be gradually withdrawn.', 2),
('c3000000-0000-0000-0000-000000000020', 'First-line treatment is topical metronidazole or ivermectin; oral tetracyclines such as doxycycline are used for more inflammatory or resistant disease.', 3),
('c3000000-0000-0000-0000-000000000021', 'Hidradenitis suppurativa is a chronic inflammatory condition of apocrine gland-bearing skin (axillae, groin, perianal, inframammary), causing recurrent painful nodules, abscesses, sinus tracts and scarring.', 1),
('c3000000-0000-0000-0000-000000000021', 'Smoking and obesity are major modifiable risk factors and should be addressed as part of management.', 2),
('c3000000-0000-0000-0000-000000000021', 'Management is stepwise: lifestyle modification, topical/oral antibiotics for flares, and referral to dermatology/surgery for severe or refractory disease.', 3),
('c3000000-0000-0000-0000-000000000022', 'Hot tub folliculitis is caused by Pseudomonas aeruginosa from inadequately chlorinated or maintained warm water, typically affecting swimwear-covered areas.', 1),
('c3000000-0000-0000-0000-000000000022', 'It is usually self-limiting, though topical antiseptics or antibiotics may be used for more extensive or symptomatic cases.', 2),
('c3000000-0000-0000-0000-000000000022', 'This should be distinguished from Staphylococcus aureus folliculitis, the most common overall cause of folliculitis, which lacks the specific hot tub exposure history.', 3),
('c3000000-0000-0000-0000-000000000023', 'Seborrhoeic dermatitis classically affects sebaceous gland-rich areas: scalp, eyebrows, nasolabial folds, and retroauricular skin, with erythema and greasy scale.', 1),
('c3000000-0000-0000-0000-000000000023', 'It is associated with Malassezia yeast overgrowth and is more common and severe in immunosuppressed patients, including those with HIV.', 2),
('c3000000-0000-0000-0000-000000000023', 'First-line treatment is topical antifungal such as ketoconazole, with or without a mild topical corticosteroid for flares.', 3),
('c3000000-0000-0000-0000-000000000024', 'Isotretinoin is a potent teratogen; a pregnancy prevention programme with contraception and pregnancy testing is mandatory for anyone who could become pregnant.', 1),
('c3000000-0000-0000-0000-000000000024', 'Baseline and periodic monitoring should include liver function tests and lipid profile, given risks of hepatotoxicity and hypertriglyceridaemia.', 2),
('c3000000-0000-0000-0000-000000000024', 'Patients should also be counselled about mood changes and the association with depression, with appropriate psychological safety-netting.', 3),
('c3000000-0000-0000-0000-000000000025', 'Alopecia areata causes non-scarring, well-demarcated patches of hair loss with normal underlying scalp skin, and exclamation mark hairs at the margin during active disease.', 1),
('c3000000-0000-0000-0000-000000000025', 'It is an autoimmune condition associated with other autoimmune diseases such as thyroid disease and vitiligo.', 2),
('c3000000-0000-0000-0000-000000000025', 'Most localised cases resolve spontaneously within a year, though intralesional or topical corticosteroids may be used to hasten regrowth.', 3),
('c3000000-0000-0000-0000-000000000026', 'Androgenetic alopecia causes a patterned, gradual hair thinning, with temporal recession and vertex thinning in men, and a strong genetic predisposition.', 1),
('c3000000-0000-0000-0000-000000000026', 'Topical minoxidil and oral finasteride are the main evidence-based treatments; finasteride requires careful counselling around teratogenicity risk to female partners/contacts, and sexual side effects.', 2),
('c3000000-0000-0000-0000-000000000026', 'A temporary increase in hair shedding can occur in the first weeks of minoxidil treatment and does not indicate treatment failure.', 3),
('c3000000-0000-0000-0000-000000000027', 'Tinea capitis presents with scaling, broken hairs of varying lengths, and sometimes inflammation, alopecia or a kerion, a boggy, pustular, inflamed swelling.', 1),
('c3000000-0000-0000-0000-000000000027', 'Oral, systemic, antifungal treatment is required, as topical treatment alone cannot eradicate infection within the hair follicle.', 2),
('c3000000-0000-0000-0000-000000000027', 'Affected children can usually continue attending school, but close contacts should be examined and treated if infected, as it is contagious.', 3),
('c3000000-0000-0000-0000-000000000028', 'Mycological confirmation via nail clippings for microscopy and culture is recommended before starting systemic antifungal treatment for suspected onychomycosis, as other conditions can mimic it.', 1),
('c3000000-0000-0000-0000-000000000028', 'Oral terbinafine is generally more effective than topical treatment for nail infections, particularly toenails, but requires consideration of hepatotoxicity risk and baseline/monitoring liver function tests.', 2),
('c3000000-0000-0000-0000-000000000028', 'Diabetic patients are at higher risk of onychomycosis and its complications, such as secondary bacterial infection, so treatment should not be dismissed as purely cosmetic.', 3),
('c3000000-0000-0000-0000-000000000029', 'Nail pitting, onycholysis, and subungual hyperkeratosis are common in psoriasis and are particularly associated with psoriatic arthritis.', 1),
('c3000000-0000-0000-0000-000000000029', 'Distal interphalangeal joint involvement is a characteristic pattern of psoriatic arthritis and often correlates with adjacent nail disease.', 2),
('c3000000-0000-0000-0000-000000000029', 'Early rheumatology referral and treatment of psoriatic arthritis is important to prevent progressive joint damage.', 3),
('c3000000-0000-0000-0000-000000000030', 'Primary focal hyperhidrosis is typically bilateral and symmetrical, affecting palms, soles or axillae, with onset often in childhood/adolescence and no identifiable secondary cause.', 1),
('c3000000-0000-0000-0000-000000000030', 'Secondary hyperhidrosis, due to conditions such as hyperthyroidism, infection or malignancy, should be considered if sweating is generalised, asymmetrical, or accompanied by systemic symptoms.', 2),
('c3000000-0000-0000-0000-000000000030', 'First-line treatment is topical aluminium chloride; further options include iontophoresis, botulinum toxin injections, oral anticholinergics, or surgery for resistant cases.', 3),
('c3000000-0000-0000-0000-000000000031', 'Scabies causes intense nocturnal itching with burrows classically in finger webs, wrists, and the genital area, and spreads readily to close contacts.', 1),
('c3000000-0000-0000-0000-000000000031', 'Treatment, using topical permethrin or malathion if contraindicated, must be applied to the whole body and given simultaneously to the patient and all household/close contacts, regardless of symptoms.', 2),
('c3000000-0000-0000-0000-000000000031', 'Itch can persist for several weeks after successful treatment, known as post-scabetic itch, and does not necessarily indicate treatment failure or reinfestation.', 3),
('c3000000-0000-0000-0000-000000000032', 'Non-bullous impetigo is a superficial bacterial skin infection presenting with golden-crusted erosions, most commonly caused by Staphylococcus aureus.', 1),
('c3000000-0000-0000-0000-000000000032', 'Localised impetigo is treated with topical antibiotics/antiseptics; more extensive or bullous impetigo may need oral antibiotics.', 2),
('c3000000-0000-0000-0000-000000000032', 'Affected children should be excluded from school/nursery until lesions have healed/crusted over or 48 hours after starting appropriate antibiotics, given its contagious nature.', 3),
('c3000000-0000-0000-0000-000000000033', 'Cellulitis is a spreading bacterial skin and soft tissue infection, typically caused by Streptococcus pyogenes or Staphylococcus aureus, presenting with erythema, warmth, swelling and poorly defined margins.', 1),
('c3000000-0000-0000-0000-000000000033', 'Systemic signs of infection, such as fever or tachycardia, or significant comorbidity such as diabetes, generally indicate a need for admission and intravenous antibiotics rather than oral outpatient treatment.', 2),
('c3000000-0000-0000-0000-000000000033', 'Necrotising fasciitis should always be considered in severe, rapidly progressing, or disproportionately painful soft tissue infection, as it is a surgical emergency requiring urgent debridement.', 3),
('c3000000-0000-0000-0000-000000000034', 'Necrotising fasciitis classically presents with pain disproportionate to visible skin changes, rapid progression, systemic toxicity, and later signs such as crepitus, skin necrosis or bullae.', 1),
('c3000000-0000-0000-0000-000000000034', 'It is a surgical emergency: definitive treatment is urgent surgical debridement, which should not be delayed for imaging when clinical suspicion is high, alongside broad-spectrum antibiotics and resuscitation.', 2),
('c3000000-0000-0000-0000-000000000034', 'Diabetes and immunosuppression are recognised risk factors for necrotising fasciitis.', 3),
('c3000000-0000-0000-0000-000000000035', 'Tinea corporis presents as an annular, scaly plaque with an active, advancing edge and central clearing, caused by dermatophyte fungi.', 1),
('c3000000-0000-0000-0000-000000000035', 'Zoonotic transmission from animals such as cats and dogs is common, particularly with Microsporum canis.', 2),
('c3000000-0000-0000-0000-000000000035', 'Topical corticosteroids should be avoided as they can mask and worsen fungal infections, known as tinea incognito; topical antifungals are first-line for localised disease.', 3),
('c3000000-0000-0000-0000-000000000036', 'Chronic plaque psoriasis classically presents with well-demarcated erythematous plaques with silvery scale on extensor surfaces, with pinpoint bleeding on scale removal, known as the Auspitz sign.', 1),
('c3000000-0000-0000-0000-000000000036', 'First-line treatment is a topical vitamin D analogue combined with a potent topical corticosteroid; systemic treatment is reserved for more severe or resistant disease.', 2),
('c3000000-0000-0000-0000-000000000036', 'Patients with psoriasis should be screened for joint symptoms (psoriatic arthritis) and cardiovascular risk factors, as psoriasis is associated with metabolic syndrome.', 3),
('c3000000-0000-0000-0000-000000000037', 'Guttate psoriasis presents with an acute eruption of small, teardrop-shaped, scaly papules on the trunk and proximal limbs, often triggered by streptococcal throat infection, particularly in children and young adults.', 1),
('c3000000-0000-0000-0000-000000000037', 'It is usually self-limiting over weeks to months, though phototherapy may be used if resolution is slow or the rash is extensive.', 2),
('c3000000-0000-0000-0000-000000000037', 'A minority of patients with guttate psoriasis go on to develop chronic plaque psoriasis.', 3),
('c3000000-0000-0000-0000-000000000038', 'Dactylitis, described as a sausage digit, and enthesitis, such as Achilles tendon or plantar fascia insertion pain, are characteristic features of psoriatic arthritis.', 1),
('c3000000-0000-0000-0000-000000000038', 'Psoriatic arthritis can affect any pattern of joints and may occur with minimal or no correlation to skin disease severity.', 2),
('c3000000-0000-0000-0000-000000000038', 'Early specialist assessment and treatment of psoriatic arthritis is important to prevent progressive, irreversible joint damage.', 3),
('c3000000-0000-0000-0000-000000000039', 'Pityriasis rosea classically begins with a single herald patch, followed by a widespread eruption of smaller oval lesions distributed along skin cleavage lines, forming a Christmas tree pattern on the back.', 1),
('c3000000-0000-0000-0000-000000000039', 'It is generally self-limiting, resolving over 6-12 weeks without specific treatment; symptomatic relief with emollients or antihistamines can be offered.', 2),
('c3000000-0000-0000-0000-000000000039', 'Secondary syphilis is an important differential, particularly if there are risk factors or palmoplantar involvement, and serology should be considered if there is diagnostic uncertainty.', 3),
('c3000000-0000-0000-0000-000000000040', $x$Lichen planus classically presents with the six Ps: pruritic, purple, polygonal, planar (flat-topped) papules and plaques, often with Wickham's striae.$x$, 1),
('c3000000-0000-0000-0000-000000000040', 'Oral involvement, such as white reticulate streaks, sometimes erosive, is common and can occur independently of skin lesions.', 2),
('c3000000-0000-0000-0000-000000000040', 'Certain drugs, including thiazide diuretics, antimalarials, and gold, can trigger lichenoid drug eruptions, so a recent medication history should always be reviewed.', 3),
('c3000000-0000-0000-0000-000000000041', 'Basal cell carcinoma classically presents as a slow-growing, pearly/translucent nodule with telangiectasia, often with central ulceration, on sun-exposed skin.', 1),
('c3000000-0000-0000-0000-000000000041', 'BCC is locally invasive but has very low metastatic potential, so referral is generally routine rather than via the urgent two-week-wait pathway, unlike melanoma or SCC with concerning features.', 2),
('c3000000-0000-0000-0000-000000000041', 'Treatment is usually surgical excision, though other options such as curettage and cautery, cryotherapy, topical treatment, or radiotherapy may be used depending on subtype and site.', 3),
('c3000000-0000-0000-0000-000000000042', 'Squamous cell carcinoma typically presents as a hyperkeratotic, ulcerated or crusted nodule, often on sun-exposed skin, and grows more rapidly than BCC.', 1),
('c3000000-0000-0000-0000-000000000042', 'Immunosuppression, such as post-transplant, is a major risk factor for SCC and is associated with more aggressive disease.', 2),
('c3000000-0000-0000-0000-000000000042', 'Unlike BCC, SCC carries a meaningful risk of metastasis, so suspected lesions warrant urgent (2-week-wait) referral.', 3),
('c3000000-0000-0000-0000-000000000043', 'The ABCDE criteria, Asymmetry, Border irregularity, Colour variation, Diameter over 6mm, Evolution/change, help identify pigmented lesions suspicious for melanoma.', 1),
('c3000000-0000-0000-0000-000000000043', 'Suspected melanoma requires urgent (2-week-wait) referral; diagnostic excision biopsy, not shave or punch biopsy, is preferred to allow accurate Breslow thickness measurement.', 2),
('c3000000-0000-0000-0000-000000000043', 'Breslow thickness is the most important prognostic factor in melanoma, guiding further management such as margins and sentinel node biopsy.', 3),
('c3000000-0000-0000-0000-000000000044', 'Actinic keratoses are common, sun-induced premalignant lesions presenting as rough, scaly, erythematous patches, most often on chronically sun-exposed skin.', 1),
('c3000000-0000-0000-0000-000000000044', 'A minority of actinic keratoses progress to squamous cell carcinoma; signs such as increasing thickness, induration, tenderness, ulceration or rapid growth should prompt urgent assessment for possible transformation.', 2),
('c3000000-0000-0000-0000-000000000044', 'Stable, uncomplicated actinic keratoses can be treated with cryotherapy, topical fluorouracil, or other field-directed therapies.', 3),
('c3000000-0000-0000-0000-000000000045', 'Seborrhoeic keratoses are common, benign, warty lesions with a characteristic stuck-on appearance, increasing in frequency with age.', 1),
('c3000000-0000-0000-0000-000000000045', 'They are typically long-standing and unchanged, unlike melanoma, which shows evolving asymmetry, border irregularity and colour variation.', 2),
('c3000000-0000-0000-0000-000000000045', 'Reassurance is usually all that is needed, though removal such as cryotherapy or curettage can be offered for symptomatic or cosmetically bothersome lesions, or if there is diagnostic uncertainty.', 3),
('c3000000-0000-0000-0000-000000000046', 'Erythema nodosum presents as tender, erythematous nodules typically on the shins, often with systemic symptoms such as fever and arthralgia.', 1),
('c3000000-0000-0000-0000-000000000046', 'Recognised causes include streptococcal infection, sarcoidosis, inflammatory bowel disease, tuberculosis, and certain drugs such as the combined oral contraceptive pill and sulfonamides; many cases are idiopathic.', 2),
('c3000000-0000-0000-0000-000000000046', 'Initial investigations should look for an underlying cause, such as throat swab/ASOT, chest X-ray, and inflammatory markers, guided by clinical suspicion.', 3),
('c3000000-0000-0000-0000-000000000047', 'Pyoderma gangrenosum is a neutrophilic dermatosis strongly associated with inflammatory bowel disease, rheumatoid arthritis, and haematological malignancy, though it can be idiopathic.', 1),
('c3000000-0000-0000-0000-000000000047', 'Classic features are a rapidly enlarging, painful ulcer with a violaceous, undermined border and a sterile wound culture, often initially misdiagnosed as infection.', 2),
('c3000000-0000-0000-0000-000000000047', 'Diagnosis is largely clinical, a diagnosis of exclusion; treatment focuses on immunosuppression such as corticosteroids rather than antibiotics or aggressive debridement, which can worsen the condition.', 3),
('c3000000-0000-0000-0000-000000000048', 'Necrobiosis lipoidica presents as well-demarcated, yellow-brown, atrophic plaques with telangiectasia, typically on the shins, and is strongly associated with diabetes mellitus.', 1),
('c3000000-0000-0000-0000-000000000048', 'Lesions can ulcerate, and patients should be advised about skin protection and monitoring for ulceration.', 2),
('c3000000-0000-0000-0000-000000000048', 'It should prompt review of diabetic control, though the skin condition itself does not necessarily correlate with glycaemic control.', 3),
('c3000000-0000-0000-0000-000000000049', 'Acanthosis nigricans typically reflects insulin resistance, such as obesity, type 2 diabetes, or PCOS, presenting as velvety hyperpigmented thickening in skin folds like the axillae, neck, and groin.', 1),
('c3000000-0000-0000-0000-000000000049', 'Rapid onset, particularly in older or non-obese patients, or with systemic features such as weight loss, should raise suspicion of malignant acanthosis nigricans, most classically associated with gastric adenocarcinoma.', 2),
('c3000000-0000-0000-0000-000000000049', 'This red flag presentation warrants prompt investigation for an underlying malignancy rather than being managed as simple insulin-resistance-related skin change.', 3),
('c3000000-0000-0000-0000-000000000050', $x$Dermatomyositis presents with proximal muscle weakness alongside characteristic skin signs: a heliotrope rash of violaceous periorbital discolouration, and Gottron's papules over the knuckles.$x$, 1),
('c3000000-0000-0000-0000-000000000050', 'Adult, particularly older-onset, dermatomyositis has a recognised association with underlying malignancy, warranting age-appropriate cancer screening.', 2),
('c3000000-0000-0000-0000-000000000050', 'Raised creatine kinase reflects muscle involvement; management involves specialist input from rheumatology, dermatology, and neurology, with immunosuppressive treatment and malignancy screening.', 3);
